/* Özgün, kaynak bağlantılı ders anlatımları ve anlatım içine yerleşen şekiller. */
(() => {
  const reading = {};
  const B = (heading, text, kind, labels, caption) => ({ heading, text, figure: { kind, labels: labels.map(([title, text]) => ({ title, text })) }, caption });
  const pages = {
    tar: [9,12,14,28,38,47,58,73,91,103,126,149,157,177],
    cog: [9,14,19,24,32,36,42,60,65,77,92,102,106,111,36,49,29],
    'fiz-tyt': [9,15,59,26,45,133,87,108,122,147],
    'fiz-ayt': [85,70,137,175,166,103,113,130,185,249]
  };
  const extraPages = {
    'tar-03':[18,21,23], 'tar-04':[32,34], 'tar-05':[40,44], 'tar-06':[49,51,55],
    'tar-07':[60,62,65], 'tar-08':[76,77,78,81], 'tar-09':[88], 'tar-10':[98,114,115],
    'tar-11':[127,128], 'tar-12':[150,154], 'tar-13':[160,161,162,164,167,173,174], 'tar-14':[181],
    'cog-02':[16], 'cog-03':[21,23], 'cog-04':[26], 'cog-05':[34], 'cog-06':[39],
    'cog-07':[45], 'cog-08':[62], 'cog-09':[67,70,71], 'cog-10':[84,88], 'cog-11':[96],
    'cog-13':[108], 'cog-14':[114,117], 'cog-16':[55], 'cog-17':[26,30],
    'fiz-tyt-01':[12,13,27], 'fiz-tyt-02':[17,20,22], 'fiz-tyt-03':[63,67,70,72],
    'fiz-tyt-04':[32,39], 'fiz-tyt-05':[47,50], 'fiz-tyt-06':[130,144],
    'fiz-tyt-07':[95,99], 'fiz-tyt-08':[103,118], 'fiz-tyt-09':[126],
    'fiz-tyt-10':[174,185,189,193], 'fiz-ayt-01':[9,16,21,80], 'fiz-ayt-02':[57,73],
    'fiz-ayt-03':[51,54,144,157,161], 'fiz-ayt-04':[182], 'fiz-ayt-05':[172],
    'fiz-ayt-06':[105,107], 'fiz-ayt-07':[122,124], 'fiz-ayt-08':[135],
    'fiz-ayt-09':[190,194,197], 'fiz-ayt-10':[208,212,235,237,238,242,244,258]
  };
  const blockPages = {
    tar: [[9,9],[12,13],[18,21],[30,34],[38,46],[51,52],[58,60],[73,77],[91,93],[103,115],[127,128],[149,154],[162,174],[177,181]],
    cog: [[9,10],[14,16],[21,23],[24,26],[32,34],[36,39],[42,45],[62,64],[65,70],[77,84],[92,96],[102,92],[106,108],[111,114],[36,38],[49,55],[30,28]],
    'fiz-tyt': [[12,29],[17,22],[63,67],[30,39],[45,50],[133,144],[87,95],[110,113],[122,126],[147,193]],
    'fiz-ayt': [[16,85],[70,73],[54,144],[175,182],[166,172],[103,107],[113,124],[130,135],[185,190],[249,258,238,244]]
  };
  const R = (id, lead, ...blocks) => {
    let sources;
    if (id === 'tar-15' || id === 'tar-16') {
      sources = [{ title: 'OGM Materyal · Defterim Tarih 9', url: 'https://ogmmateryal.eba.gov.tr/panel/upload/etkilesimli/kitap/defterim/9/tarih/files/basic-html/page' + (id === 'tar-15' ? '36' : '46') + '.html' }];
      if(id === 'tar-16') sources.push({ title: 'OGM Materyal · Medeniyet havzaları, devamı', url: 'https://ogmmateryal.eba.gov.tr/panel/upload/etkilesimli/kitap/defterim/9/tarih/files/basic-html/page47.html' });
      blocks.forEach((block,i)=>{block.source=sources[id==='tar-16'?i:0];});
    } else {
      const group=id.replace(/-\d+$/,''), n=Number(id.match(/\d+$/)[0])-1;
      const book={tar:'TYT-tar',cog:'TYT-cog','fiz-tyt':'TYT-fiz','fiz-ayt':'AYT-fiz'}[group];
      blocks.forEach((block,i)=>{block.source={book,page:blockPages[group][n][i]};});
      sources=[...new Set([pages[group][n],...(extraPages[id]||[]),...blocks.map(b=>b.source.page)])].sort((a,b)=>a-b).map(page=>({book,page}));
    }
    reading[id] = { lead, blocks, sources };
  };

  R('tar-01','Tarihsel bilgi, geçmişten kalan kanıtların dönem koşulları içinde sorgulanmasıyla kurulur.',
    B('Bir olayı tarihsel yapan bağlam',`Tarih, geçmişte olmuş her şeyi sıralayan bir takvim değildir. İnsanların faaliyetlerini yer, zaman ve koşullarıyla birlikte açıklar. Örneğin bir göçün hangi yılda gerçekleştiğini bilmek başlangıçtır; göçün nedenlerini, izlenen yolları ve karşılaşılan toplumları araştırmak tarihsel açıklamayı kurar. Belirli bir savaşı olay, uzun sürede gelişen kentleşmeyi olgu olarak düşün. Olayın sınırları daha belirginken olgu, birçok olayın ortak etkisiyle ortaya çıkabilir. Bu ayrım, kısa bir gelişmeden geniş bir sürecin tamamına hükmetmeni önler.`, 'compare', [['Olay','Belirli yer ve zamanda gerçekleşen gelişme'],['Olgu','Uzun sürede ortaya çıkan genel değişim'],['Bağlam','Olayın dönem koşulları ve ilişkileri']], 'Olay ile olgu birbirinden kopuk değil, farklı ölçeklerde incelenir.'),
    B('Kanıtı eleştirmek, yorumu güçlendirmek',`Araştırmacı önce sorusuna uygun kaynakları toplar; ardından bunların gerçekliğini, oluşma zamanını ve amaçlarını sorgular. Döneme ait bir kitabe birinci el kaynak olabilir, fakat hükümdarı övmek amacıyla yazılmış olması yorumda dikkate alınmalıdır. Birden fazla bağımsız kanıtın karşılaştırılması güveni artırır. Yeni bir belgenin eski görüşü değiştirmesi tarihin keyfî olduğu anlamına gelmez; bilginin kanıtla sınanabildiğini gösterir. Geçmişin insanlarını bugünün bütün değer ve imkânlarına sahipmiş gibi değerlendirmek ise dönem bağlamını kaybettirir.`, 'process', [['Kaynak toplama','Belge, kalıntı ve tanıklık'],['Eleştiri','Gerçeklik, amaç ve güvenilirlik'],['Karşılaştırma','Birbirini destekleyen veya çelişen kanıtlar'],['Yorum','Kanıtla gerekçelendirilen açıklama']], 'Yorumun gücü, yalnız kaynak sayısından değil kaynakların nasıl sorgulandığından gelir.'));

  R('tar-02','Kronoloji olayların sırasını kurar; takvim ise zamanı ölçmek için toplumun benimsediği sistemdir.',
    B('Milattan önce ve sonra doğru sıralama',`Bir zaman çizgisinde milattan önceki tarihlerden milada doğru gelirken yıl sayısı küçülür. Bu nedenle MÖ 500, MÖ 200’den daha eskidir. Milattan sonra ise sayı büyüdükçe günümüze yaklaşılır. MÖ 1’i MS 1 izler; kullanılan tarih sisteminde sıfır yılı yoktur. Yüzyıl hesaplarında da sınırları dikkatle izle: 1801–1900 aralığı on dokuzuncu yüzyıldır. Böylece 1900 ile 1901’in farklı yüzyıllara girdiğini, yalnız ilk iki rakama bakmadan anlayabilirsin.`, 'timeline', [['MÖ 500','Daha eski'],['MÖ 200','Milada daha yakın'],['MÖ 1 → MS 1','Sıfır yılı yok'],['1900 → 1901','Yüzyıl sınırı']], 'Çizginin sağında günümüze yaklaşılır; MÖ bölümünde sayılar azalır.'),
    B('Takvim değişince geçmiş değişmez',`Takvimler zamanı gün, ay ve yıl gibi birimlere ayırır; ancak başlangıç kabul ettikleri olay ve dayandıkları gök hareketi farklı olabilir. Hicri takvim hicreti başlangıç alır ve ay yılına dayanır. Miladi takvim güneş yılı esaslıdır. Aynı olayın bu sistemlerde farklı tarihlerle yazılması iki ayrı olay bulunduğunu göstermez. Yazının kullanılmaya başlanması tarih öncesi ve tarihî dönem ayrımında ölçüt kabul edilir; toplumların yazıyı farklı zamanlarda öğrenmesi, bu ayrımın her yerde eş zamanlı olmadığını gösterir.`, 'compare', [['Başlangıç','Takvimin sıfır kabul ettiği dönüm noktası'],['Yıl türü','Ay veya güneş hareketi'],['Tarihî dönem','Yazılı kayıtların kullanılması']], 'Takvim tarihi ifade etme aracıdır; olayın kendisiyle karıştırılmaz.'));

  R('tar-03','İlk Türk toplumlarında coğrafya, ekonomik yaşam ve siyasi teşkilatlanma birlikte okunmalıdır.',
    B('Bozkır koşullarından toplumsal örgütlenmeye',`Orta Asya’nın geniş otlakları ve karasal koşulları, hayvancılıkla geçinen toplulukların mevsimlere göre yer değiştirmesini destekledi. Bu hareketlilik plansız dolaşma anlamına gelmez; yaylak ve kışlak arasında üretime bağlı bir düzen vardır. Ailelerin ve soy gruplarının oluşturduğu boylar, daha geniş siyasi birliklerin temelini oluşturdu. Atın günlük yaşam ve ulaşımda kullanılması hareket kabiliyetini artırdı. Coğrafya yaşam biçimini etkilerken toplumlar da ihtiyaçlarına uygun askerî ve idari örgütler geliştirdi; tek bir doğal koşul bütün kültürü tek başına açıklamaz.`, 'cause', [['Bozkır','Otlak ve karasal iklim'],['Üretim','Hayvancılık ve mevsimlik hareket'],['Toplum','Aile, boy ve daha geniş birlikler'],['Hareketlilik','Ulaşım ve askerî kabiliyet']], 'Coğrafi koşul bir etkendir; kültürün bütününü tek başına belirleyen neden değildir.'),
    B('Kut, töre ve kurultayın farklı görevleri',`Kut anlayışı hükümdarın yönetme yetkisini ilahî bir kaynağa dayandırır. Töre ise toplum ve yönetim için geçerli kuralları ifade eder; hükümdarın da bu kurallara uyması beklenir. Kurultay devlet meselelerinin görüşüldüğü ortamdır. Bu kavramları tek bir kurum gibi düşünme: biri meşruiyeti, biri kuralları, diğeri kararların görüşülmesini anlatır. Hanedan üyelerinin yönetimde hak sahibi sayılması taht mücadelelerine yol açabilir. Uygurların yerleşik yaşamı geliştirmesi ise mimari ve yazılı kültürde farklı imkânlar doğurmuştur.`, 'compare', [['Kut','Yönetme yetkisinin meşruiyeti'],['Töre','Bağlayıcı toplumsal kurallar'],['Kurultay','Devlet meselelerinin görüşülmesi'],['Hanedan','Veraset ve taht mücadeleleri']], 'Bir yönetim düzenini anlamak için yetkinin kaynağıyla uygulanma biçimini ayır.'));

  R('tar-04','İslam tarihindeki yönetim ve kültür değişimlerini, dönemlerin sırasına yerleştirerek öğren.',
    B('Hicret ve siyasi topluluğun gelişmesi',`İslamiyet’in doğduğu dönemde Arabistan’ın çevresinde Doğu Roma ve Sasani gibi büyük güçler bulunuyordu. Ticaret yolları, kabile ilişkileri ve farklı inançlar bölgenin toplumsal yapısını etkiliyordu. 622’deki hicret, Müslümanların Mekke’den Medine’ye göçünü ifade eder. Medine’de ortak yaşamın ve siyasi örgütlenmenin gelişmesi, bu olayı yalnız bir yer değiştirmeden daha önemli hâle getirir. Hz. Muhammed’in vefatından sonra başlayan Dört Halife döneminde ise yönetimin devamı, fetihler ve kurumlaşma yeni ihtiyaçlar doğurmuştur.`, 'timeline', [['Arabistan','Ticaret, kabileler ve farklı inançlar'],['622 Hicret','Medine’ye göç'],['Medine','Toplumsal ve siyasi örgütlenme'],['Dört Halife','Yönetim ve kurumlaşmanın sürmesi']], 'Hicretin önemi, yer değiştirmenin ardından gelişen toplumsal ve siyasi yapıyla anlaşılır.'),
    B('Hanedan yönetimi ve kültürel etkileşim',`Emeviler döneminde halifeliğin hanedan içinde aktarılması, yönetimin saltanat niteliği kazanması bakımından ayırt edicidir. Arap olmayan Müslümanlara yönelik uygulamalar toplumsal gerilimleri artırmıştır. Abbasiler döneminde farklı toplulukların yönetim ve kültür hayatındaki rolü güçlenirken Bağdat önemli bir merkez olmuştur. Çeviri çalışmaları, başka uygarlıkların birikiminin tanınmasına ve geliştirilmesine imkân sağlamıştır. Burada siyasi yönetim değişimiyle bilimsel etkileşimi ayrı alanlar olarak gör; aynı dönemde yaşanmaları, her gelişmenin tek bir nedene indirgenmesini gerektirmez.`, 'compare', [['Emeviler','Hanedan içinde halifelik'],['Toplumsal yapı','Arap olmayan Müslümanların durumu'],['Abbasiler','Farklı toplulukların artan rolü'],['Bilim','Çeviri ve ortak birikim']], 'Saltanat siyasi bir yönetim biçimini, çeviri faaliyetleri kültürel etkileşimi anlatır.'));

  R('tar-05','Türklerin İslamlaşması ve Türk-İslam kurumlarının gelişmesi uzun süreli bir etkileşim sürecidir.',
    B('Yakınlaşmayı tek savaşa indirgeme',`751 Talas Savaşı, Türkler ile Abbasiler arasındaki yakınlaşmada önemli bir dönüm noktasıdır; ancak bütün Türk topluluklarının aynı anda din değiştirdiği anlamına gelmez. Ticaret, siyasi ilişkiler ve farklı bölgelerdeki temaslar süreci zaman içinde geliştirmiştir. Karahanlılar döneminde İslamiyet devlet ve toplum yaşamında belirginleşirken Türkçe kültür geleneği de sürmüştür. Gaznelilerin Hindistan yönündeki seferleri İslamiyet’in bu bölgede yayılmasına katkı sağlamıştır. Büyük Selçukluların güçlenmesiyle Türklerin İslam dünyasındaki siyasi etkisi daha da artmıştır.`, 'timeline', [['751 Talas','Yakınlaşmada dönüm noktası'],['Karahanlılar','İslamlaşma ve Türkçe kültür'],['Gazneliler','Hindistan yönünde etki'],['Selçuklular','Genişleyen siyasi güç']], 'Bir dönüm noktası, uzun sürecin bütün nedenlerinin yerine geçmez.'),
    B('Kurumlar hangi ihtiyaca cevap verdi?',`Türk-İslam devletlerinde eski yönetim gelenekleri yeni dinî ve idari kurumlarla birlikte varlığını sürdürdü. Medreseler eğitim ve bilgin yetiştirmeyle, kervansaraylar ticaretin güvenliği ve sürekliliğiyle ilişkiliydi. İkta uygulamasında belirli toprakların vergi gelirleri hizmet karşılığında görevlilere bırakılabiliyordu. Bu gelir asker yetiştirilmesini ve üretimin sürmesini destekliyordu. Toprağın gelirini kullanma yetkisini, toprağın bütünüyle özel mülkiyete geçirilmesiyle karıştırma. Kurumları adlarıyla ezberlemek yerine eğitim, ekonomi ve askerlik ihtiyaçlarına bağlamak daha kalıcı bir açıklama sağlar.`, 'compare', [['Medrese','Eğitim ve bilgi üretimi'],['Kervansaray','Güvenli ticaret ve konaklama'],['İkta','Vergi geliri karşılığında hizmet'],['Askerî sonuç','Gelirle asker yetiştirme']], 'İkta, ekonomi ile askerî teşkilat arasında kurulan bir bağlantıdır.'));

  R('tar-06','Anadolu’daki Türk varlığının kalıcılaşması savaşların yanında yerleşme ve kültür üretimiyle gelişti.',
    B('Üç savaş, üç farklı eşik',`1071 Malazgirt zaferi Anadolu’ya yönelen Türk göçlerini ve fetihlerini hızlandırdı. Ardından kurulan ilk Türk beylikleri, farklı bölgelerde siyasi ve kültürel merkezler oluşturdu. 1176 Miryokefalon, Bizans’ın Türkleri Anadolu’dan çıkarma girişimlerini zayıflatarak kalıcılığı güçlendiren bir dönüm noktasıdır. Buna karşılık 1243 Kösedağ yenilgisi, Türkiye Selçuklu yönetimi üzerindeki Moğol baskısını artırdı. Bu tarihler aynı sonucu anlatmaz: ilkinde yerleşmenin önü açılır, ikincisinde kalıcılık güçlenir, üçüncüsünde merkezî güç zayıflar ve siyasi parçalanma belirginleşir.`, 'timeline', [['1071 Malazgirt','Göç ve fetihlerin hızlanması'],['İlk beylikler','Yerel siyasi ve kültürel merkezler'],['1176 Miryokefalon','Kalıcılığın güçlenmesi'],['1243 Kösedağ','Moğol baskısı ve merkezî zayıflama']], 'Kronoloji, aynı coğrafyada yaşanan olayların farklı sonuçlarını ayırır.'),
    B('Fethedilen yer nasıl yurt olur?',`Bir bölgenin askerî olarak ele geçirilmesi, orada kalıcı toplumsal hayatın hemen tamamlandığını göstermez. Köy ve şehirlerin kurulması, üretimin sürmesi, cami ve medrese gibi yapıların inşası yerleşmeyi derinleştirir. Türkiye Selçukluları ticaret yollarını ve limanları önemsemiş, kervansaraylarla tüccarlara güvenli konaklama sağlamıştır. Böylece fetih, nüfus yerleşmesi ve ekonomik ağlar birbirini desteklemiştir. Soru bir kervansaraydan söz ediyorsa önce ticaret ve güvenlik işlevini düşün; bu yapıdan doğrudan yalnız askerî başarı sonucu çıkarma.`, 'cause', [['Yerleşme','Köy ve şehir yaşamı'],['Kültür','Eğitim ve dinî yapılar'],['Ticaret','Liman, yol ve kervansaray'],['Kalıcılık','Birbirini destekleyen toplumsal ağ']], 'Yurtlaşma tek bir savaşın değil, birbirine bağlanan faaliyetlerin sonucudur.'));

  R('tar-07','Osmanlı’nın büyümesi, siyasi fırsatların kalıcı yönetim politikalarıyla birleştirilmesiyle açıklanır.',
    B('Kuruluş ortamındaki fırsatlar',`Osmanlı Beyliği, Bizans sınırındaki uç bölgesinde ortaya çıktı. Bizans’ın iç mücadeleleri, Anadolu’daki siyasi parçalanma ve Balkanlardaki bölünmüş yapı fetihler için elverişli koşullar sağladı. Ancak uygun ortam tek başına büyümeyi açıklamaz; askerî örgütlenme, yerel destek ve yönetim düzeni de gereklidir. Batıya yönelen genişleme, bazı dönemlerde Anadolu’daki diğer beyliklerle mücadeleyi sınırlama imkânı verdi. Böylece coğrafi konum, çevredeki siyasi durum ve uygulanan politikalar birlikte değerlendirilmelidir. Soruda yalnız birini bütün başarının tek nedeni saymak eksik kalır.`, 'cause', [['Uç konumu','Bizans sınırında hareket alanı'],['Siyasi parçalanma','Çevredeki iç mücadeleler'],['Örgütlenme','Ordu ve idarenin gelişmesi'],['Büyüme','Koşulların politikayla değerlendirilmesi']], 'Fırsat ile o fırsattan yararlanmayı sağlayan teşkilatı birlikte düşün.'),
    B('İskân ve istimâlet birbirini tamamlar',`Fethedilen bir yerin uzun süre yönetilebilmesi için güvenlik, üretim ve halkın bağlılığı gerekir. İskân politikası, nüfusun uygun bölgelere yerleştirilmesini ve kalıcı yaşamın kurulmasını destekledi. İstimâlet ise yerel halka karşı uzlaştırıcı tutumla yeni yönetime bağlılığı artırmayı amaçladı. Bunlar aynı uygulama değildir, fakat ortak hedefleri fetihlerin kalıcılaşmasıdır. Düzenli askerî ve mali kurumların gelişmesi de genişleyen toprakların yönetimini kolaylaştırdı. Anadolu Türk siyasi birliğine yönelik girişimler ise farklı beyliklerin tek merkez altında toplanmasıyla ilişkilidir.`, 'compare', [['İskân','Nüfus yerleştirme ve üretim'],['İstimâlet','Yerel halkı yönetime kazanma'],['Teşkilat','Güvenlik ve düzenli yönetim'],['Siyasi birlik','Farklı merkezlerin birleştirilmesi']], 'Kalıcı hâkimiyet, yalnız ele geçirmeyi değil yönetebilmeyi gerektirir.'));

  R('tar-08','Fetihleri haritada yerleştir; ardından her birinin siyasi ve ekonomik sonuçlarını ayır.',
    B('İstanbul’un konumu neden önemliydi?',`İstanbul, Osmanlı’nın Anadolu ve Rumeli toprakları arasındaki bağlantı üzerinde bulunuyordu. Bizans’ın varlığı, yalnız sembolik bir mesele değil stratejik bütünlük ve siyasi güvenlik açısından da önem taşıyordu. Şehrin alınması boğazlar ve ticaret yolları üzerindeki Osmanlı etkisini güçlendirebilirdi. 1453’te fetihle Bizans Devleti sona erdi ve İstanbul Osmanlı başkenti oldu. Bir devletin sona ermesi siyasi, yollar üzerindeki etkinliğin artması ekonomik sonuçtur. Aynı olayın farklı alanlarda sonuç oluşturabileceğini bu örnekte birlikte görebilirsin.`, 'cause', [['Konum','Anadolu–Rumeli bağlantısı'],['Güvenlik','Bizans kaynaklı siyasi sorunlar'],['1453 Fetih','İstanbul’un alınması'],['Sonuç','Başkent, bütünlük ve ticari etki']], 'Bir fethin nedenleriyle sonradan ortaya çıkan sonuçlarını birbirine karıştırma.'),
    B('Kara ve deniz siyaseti birlikte gelişir',`Osmanlı’nın Karadeniz kıyıları ve Kırım üzerindeki etkisinin artması, ticaret yollarının denetimi bakımından önemlidir. Mısır’ın 1517’de alınmasıyla Memlûk Devleti sona ermiş, Osmanlı’nın Doğu Akdeniz ve İslam dünyasındaki siyasi ağırlığı artmıştır. Donanmanın güçlenmesi ise yalnız deniz savaşı kazanmak için değil kıyıları ve ticareti korumak için de gereklidir. Yabancı tüccarlara verilen ayrıcalıklar ekonomik ve diplomatik amaçlarla kullanılabilir; bu ayrıcalıkların etkisi zaman içindeki güç dengelerine göre değişir. Bütün dönemleri aynı sonuçla değerlendirmekten kaçın.`, 'compare', [['Karadeniz','Ticaret yollarındaki etki'],['Mısır','Doğu Akdeniz ve siyasi güç'],['Donanma','Deniz güvenliği ve ulaşım'],['Ayrıcalıklar','Ekonomik ve diplomatik araçlar']], 'Denizcilik, ekonomi ve devletler arası ilişkiler arasında bağ kurar.'));

  R('tar-09','Osmanlı kurumlarını, toplumun hangi ihtiyacını karşıladıklarına göre düzenle.',
    B('Toprak geliri neden askerlikle bağlantılıydı?',`Tarıma dayalı Osmanlı ekonomisinde toprağın işlenmesi, köylünün üretimi ve vergi gelirinin devamı devlet için önemliydi. Tımar sisteminde belirli toprakların vergi toplama hakkı hizmet karşılığında görevlilere bırakılabiliyordu. Bu gelirle asker yetiştirilmesi, ekonomik kaynağın askerî güce dönüştürülmesini sağlıyordu. Tımar sahibinin toprağı mutlak özel mülk edinmesiyle vergi gelirini kullanması aynı şey değildir. Üretimin aksaması yalnız köylünün geçimini değil, mali ve askerî düzeni de etkileyebileceğinden sistemin farklı parçaları birbirine bağlıydı.`, 'process', [['Toprak','Tarımsal üretim'],['Vergi geliri','Hizmet karşılığında ayrılan kaynak'],['Tımar sahibi','Görev ve asker yetiştirme'],['Ordu','Ekonomik kaynağın askerî karşılığı']], 'Tımarı yalnız toprak paylaşımı değil, üretim ve hizmet düzeni olarak oku.'),
    B('Meslek, sosyal hizmet ve cemaat düzeni',`Loncalar, esnaf ve zanaatkârları örgütleyerek mesleki eğitim ve üretim düzeninde rol üstleniyordu. Usta-çırak ilişkisi bilginin yeni kuşağa aktarılmasını sağlarken kaliteye yönelik kurallar tüketiciyi ve mesleği etkiliyordu. Vakıflar ise ayrılan gelirlerle okul, sağlık ve yardım gibi hizmetlerin sürekliliğini destekliyordu. Millet sistemi farklı bir alana aittir: gayrimüslim toplulukların din ve mezhep temelindeki örgütlenmesini anlatır. Buradaki millet kavramı modern ulusla aynı değildir. Sorudaki faaliyeti belirleyip kurumu ihtiyacıyla eşleştirmek, benzer isimleri karıştırmanı önler.`, 'compare', [['Lonca','Meslek, üretim ve çıraklık'],['Vakıf','Gelirle sürdürülen sosyal hizmet'],['Millet sistemi','Din ve mezhep temelli cemaat düzeni']], 'Kurumun adı kadar yürüttüğü faaliyet de doğru eşleştirmenin anahtarıdır.'));

  R('tar-10','Avrupa’daki dönüşümler farklı alanlarda gelişti; etkileri Osmanlı’ya farklı yollarla ulaştı.',
    B('Düşünce, din ve ticarette değişim',`Rönesans, Antik Çağ birikimine ilginin ve insan merkezli yaklaşımların sanat, bilim ve düşüncede gelişmesiyle ilişkilidir. Reform, Katolik Kilisesi’ne yönelik eleştirilerin dinî alanda yeni mezhepler doğurmasıdır. Coğrafi Keşifler ise yeni deniz yollarının ve bölgelerin tanınmasıyla ticaret ve sömürgecilik ağlarını değiştirmiştir. Bu gelişmeler birbirini etkileyebilir, fakat aynı olay değildir ve tek sıra hâlinde zorunlu bir neden zinciri oluşturmaz. Bir soruda kilise ve mezhep vurgusu varsa Reform; eser, düşünce ve bilim vurgusu varsa Rönesans yönüne bak.`, 'compare', [['Rönesans','Sanat, bilim ve düşünce'],['Reform','Dinî yapı ve mezhepler'],['Keşifler','Deniz yolları ve ticari ağlar']], 'Aynı dönemde gelişmek, aynı anlama veya tek nedene sahip olmak değildir.'),
    B('Üretim devrimi ve siyasi fikirler',`Sanayi Devrimi makineleşmeyle üretimi artırmış, ham madde ve pazar ihtiyacını güçlendirmiştir. Fabrikalar, kentleşme ve işçi sınıfı ekonomik ve toplumsal yapıyı değiştirmiştir. Fransız İhtilali ise eşitlik, ulusal egemenlik ve milliyetçilik fikirlerinin yayılmasında önemli bir dönüm noktasıdır. Çok uluslu Osmanlı yapısında milliyetçilik bağımsızlık hareketlerini etkilerken sanayi ürünleriyle rekabet yerel üretimi zorlayabiliyordu. Bir gelişmenin ekonomik, diğerinin siyasi etkisini ayırmak gerekir. Aynı devleti etkilemeleri, bu etkilerin birbirinin yerine kullanılabileceği anlamına gelmez.`, 'cause', [['Sanayileşme','Üretim, ham madde ve pazar'],['Toplumsal değişim','Kentleşme ve işçi sınıfı'],['Milliyetçilik','Ulus ve bağımsızlık talepleri'],['Osmanlı’ya etkiler','Ekonomik rekabet ve siyasi ayrışma']], 'Etkiler farklı kanallardan gelir: üretim düzeni ile siyasi fikirleri ayrı incele.'));

  R('tar-11','Hak güvencesi, hukuki eşitlik ve halkın temsili aynı yönde gelişebilse de farklı kavramlardır.',
    B('Fermanların ortak ve farklı yönleri',`1808 Sened-i İttifak, merkezî yönetim ile güçlenen ayanlar arasındaki ilişkileri düzenleyen bir uzlaşmadır. Halkın seçilmiş temsilcilerinin meclise girmesiyle aynı anlama gelmez. 1839 Tanzimat Fermanı can, mal ve namus güvenliği; vergi, askerlik ve yargılama düzeni gibi güvencelerle öne çıkar. 1856 Islahat Fermanı ise özellikle gayrimüslimlerin hakları ve hukuki eşitlikle ilişkilidir. Bu belgeleri incelerken kimin muhatap olduğunu ve hangi sorunu düzenlediğini sor. Bir hak güvencesini doğrudan seçim veya cumhuriyet olarak adlandırma.`, 'timeline', [['1808','Merkez–ayan uzlaşması'],['1839','Kişi güvenliği ve düzenlemeler'],['1856','Gayrimüslim hakları ve eşitlik']], 'İlerleyen tarihlerde farklı ihtiyaçlar öne çıkar; belgelerin işlevleri birebir aynı değildir.'),
    B('Anayasa ve temsil nasıl değişiklik getirdi?',`1876 Kanun-i Esasi’nin ilanı ve meclisin açılması, Osmanlı’da anayasal yönetim bakımından önemli bir eşiktir. Halkın seçtiği temsilcilerin yönetime katılması temsil boyutunu oluşturur. Ancak meşrutiyette hükümdar varlığını sürdürdüğü için bu gelişme saltanatın kaldırılması demek değildir. 1908’de anayasal yönetim yeniden yürürlüğe girmiş, sonraki değişikliklerle meclisin rolü güçlenmiştir. Bir askerî okulun açılması yenileşmeye örnekken seçilmiş meclis siyasi katılıma örnektir. İkisini aynı demokrasi göstergesi saymadan, değişimin hangi alanda gerçekleştiğini belirlemek gerekir.`, 'process', [['Anayasa','Yönetimin yazılı çerçevesi'],['Meclis','Temsil ve siyasi katılım'],['Meşrutiyet','Hükümdar ile anayasal kurumların birlikteliği'],['Yetki dengesi','Meclisin rolünün değişmesi']], 'Çağdaşlaşma geniş bir süreçtir; her yenilik doğrudan halkın yönetime katılımı değildir.'));

  R('tar-12','Savaşın uzun vadeli nedenlerini, Osmanlı cephelerini ve ateşkesin sonuçlarını ayrı katmanlarda incele.',
    B('Savaş ortamı ve cephe amaçları',`Sömürge rekabeti, silahlanma, bloklaşma ve milliyetçilik I. Dünya Savaşı öncesindeki gerilimi besledi. Saraybosna suikastı ise bu ortamda savaşı tetikleyen olay oldu; bütün nedenlerin yerine geçmez. Osmanlı’nın katıldığı cephelerde amaçlar farklıydı. Kafkas ve Kanal cephelerinde ilerleme hedefi öne çıkarken Çanakkale gibi cephelerde düşman ilerleyişini durdurmak esastı. Bir cephede kazanılan başarı savaşın genel sonucunun da aynı olduğunu göstermez. Her cephenin hedefini, gerçekleşen sonucu ve savaşın bütünündeki yeriyle birlikte değerlendirmek gerekir.`, 'hierarchy', [['Uzun vadeli ortam','Rekabet ve bloklaşma'],['Tetikleyici','Saraybosna suikastı'],['Taarruz amaçları','Kafkas ve Kanal'],['Savunma amaçları','Çanakkale ve diğer savunma cepheleri']], 'Neden, tetikleyici, amaç ve sonuç farklı soruların cevaplarıdır.'),
    B('Mondros neden direniş ortamı doğurdu?',`1918 Mondros Ateşkesi, ordunun önemli bölümünün terhis edilmesi ve stratejik alanların denetimi gibi hükümlerle Osmanlı’nın savunma imkânlarını zayıflattı. İşgale açık hükümler, sonradan gerçekleşen işgaller için elverişli bir ortam oluşturdu. Merkezî yönetimin etkisizliği karşısında yerel halkın güvenlik ve bağımsızlık kaygısı arttı. Müdafaa-i hukuk cemiyetleri ve Kuvayımilliye bu ortamda gelişti. Ateşkesin imzalanmasını kalıcı ve eşit koşullu bir barışla karıştırma; ateşkes savaşmayı durduran düzenleme, barış antlaşması ise daha geniş siyasi şartları belirleyen belgedir.`, 'cause', [['Terhis','Savunma gücünün azalması'],['İşgaller','Güvenlik ve bağımsızlık sorunu'],['Yerel örgütlenme','Cemiyetler ve Kuvayımilliye'],['Direniş','İşgale karşı toplumsal tepki']], 'Ateşkes hükümleriyle oluşan güç boşluğu, yerel direnişin nedenlerini açıklar.'));

  R('tar-13','Millî Mücadele’de yerel direniş, ortak program ve merkezî karar organı altında birleşti.',
    B('1919’da örgütlenmenin yönü',`İzmir’in işgali ve diğer işgaller, farklı bölgelerde direniş tepkilerini güçlendirdi. Amasya Genelgesi bağımsızlığın milletin azim ve kararıyla korunacağını belirterek mücadelede millî iradeyi esas aldı. Erzurum Kongresi bütünlük ve irade vurgusunu güçlendirdi; Sivas Kongresi millî cemiyetleri ortak bir çatı altında topladı. Buradaki değişim, birbirinden kopuk tepkilerin ortak bir hedefe yönelmesidir. Kongrelerin yalnız düzenlendikleri yerleri değil, kararlarının kapsamını da düşün. Bölgesel bir toplantı, aldığı kararlarla ülkenin tamamını ilgilendiren bir programa katkı sağlayabilir.`, 'timeline', [['İşgaller','Yerel tepkilerin güçlenmesi'],['Amasya','Millî iradenin esas alınması'],['Erzurum','Bütünlük ve bağımsızlık'],['Sivas','Cemiyetlerin ortak çatıya alınması']], 'Örgütlenmenin ölçeği yerelden ortak ulusal programa doğru genişler.'),
    B('Meclis, cephe ve diplomasi',`23 Nisan 1920’de TBMM’nin açılması, mücadelenin merkezî ve meşru karar organını oluşturdu. Düzenli ordunun kurulmasıyla askerî mücadele ortak yönetim altında sürdürüldü. İnönü savaşları ve Sakarya savunmanın güçlenmesinde, 1922 Büyük Taarruz ise kesin askerî sonuçta önemli aşamalardır. Mudanya Ateşkesi diplomatik sürece geçişi, 1923 Lozan Antlaşması bağımsızlığın uluslararası kabulünü temsil eder. Millî egemenlik yönetme yetkisinin millete ait olmasıdır; bağımsızlık ise dış baskı olmadan karar verebilmektir. Aynı süreçte güçlenirler ama birbirlerinin tam karşılığı değildirler.`, 'timeline', [['1920 TBMM','Merkezî karar ve millî egemenlik'],['1921','Savunma ve düzenli ordu'],['1922','Büyük Taarruz ve Mudanya'],['1923 Lozan','Bağımsızlığın uluslararası kabulü']], 'Askerî başarı ile diplomatik sonuç arasında ilişki vardır; ikisi aynı aşama değildir.'));

  R('tar-14','İlkeleri, inkılabın hangi sorunu çözdüğünü ve hangi sonucu doğurduğunu izleyerek eşleştir.',
    B('Siyasi yönetim ve eşitlik',`Cumhuriyetçilik, yönetimde millî egemenlik ve temsili esas alır. Halkçılık ise ayrıcalıkların reddi ve kanun önünde eşitlikle ilgilidir. Milliyetçilik bağımsızlık, ortak aidiyet ve millî birlik boyutunu taşır. Aynı uygulama birden fazla ilkeyle bağlantı kurabilir. Kadınların siyasi hak kazanması yönetime katılım açısından cumhuriyetçilikle, eşitlik açısından halkçılıkla ilişkilidir. Bu yüzden sorudaki anahtar ifade önemlidir. Yalnız olayın adını görüp tek etiket ezberlemek yerine, vurgulanan yönün yönetim, eşitlik veya birlik olup olmadığını belirle.`, 'compare', [['Cumhuriyetçilik','Millî egemenlik ve temsil'],['Halkçılık','Eşitlik ve ayrıcalıkların reddi'],['Milliyetçilik','Bağımsızlık ve ortak aidiyet']], 'Tek uygulama, vurgulanan sonucuna göre farklı ilkelerle ilişkilendirilebilir.'),
    B('Kurumlar ve kalkınma',`Laiklik, din ve devlet işlerinin ayrılması ve kamusal kurumların akılcı düzenlenmesiyle ilişkilidir. Eğitimde birliği sağlayan Tevhid-i Tedrisat, farklı eğitim yapılarının ortak çerçevede toplanmasını hedefledi. Devletçilik ise özel girişimle birlikte devletin kalkınmada yatırım ve düzenleme rolü üstlenmesini anlatır; bütün özel girişimin kaldırılması demek değildir. İnkılapçılık, yapılan dönüşümleri koruma ve çağın ihtiyaçlarına göre geliştirme anlayışıdır. Yeni harflerin kabulü veya hukuk düzenindeki değişimler incelenirken yeniliğin hedefi ve toplumdaki somut etkisi birlikte değerlendirilmelidir.`, 'compare', [['Laiklik','Din ve devlet işlerinin ayrılması'],['Eğitim birliği','Ortak kurumsal çerçeve'],['Devletçilik','Kalkınmada kamu yatırımı ve düzenleme'],['İnkılapçılık','Dönüşümü sürdürme ve geliştirme']], 'İlkenin açıklaması, uygulamanın amacıyla bağlantı kurduğunda anlaşılır.'));

  R('tar-15','Geçim biçimindeki değişim, yerleşme ve toplumsal örgütlenmenin dönüşümünü anlamak için başlangıçtır.',
    B('Üretim yerleşmeyi nasıl destekledi?',`Avcı-toplayıcı topluluklar besin kaynaklarının bulunduğu alanlara göre hareket ediyordu. Tarımın ve hayvan evcilleştirmenin yaygınlaşması, insanların besin üretimine daha çok katılmasını sağladı. Ekim yapılan alanın bakımı ve ürünün beklenmesi, belirli yerde uzun süre kalmayı destekledi. Kalıcı evler, öğütme araçları ve depolama kapları bu yaşamın farklı göstergeleridir. Bunları bir arada görmek, yalnız tek bir eşyadan daha güçlü çıkarım sağlar. Yerleşik yaşamın gelişmesi her toplumda aynı tarihte ve aynı hızda gerçekleşmedi; doğal koşullar ve etkileşim farklı yollar doğurdu.`, 'cause', [['Besin üretimi','Tarım ve evcilleştirme'],['Yere bağlılık','Üretim alanının bakımı'],['Yerleşme','Kalıcı konut ve depolama'],['Kanıt','Birbirini destekleyen bulgular']], 'Üretim, yerleşmeyi destekleyen bir süreçtir; bütün toplumlarda tek anda yaşanan değişim değildir.'),
    B('Artı ürün ve değişen işler',`İhtiyaçtan fazla ürünün depolanabilmesi, bazı insanların her gün yalnız besin aramak dışında işlere zaman ayırmasını kolaylaştırdı. Çanak çömlek, dokuma veya araç yapımı gibi faaliyetler gelişirken ürün değişimi de çeşitlenebildi. Böylece üretim, depolama ve iş bölümü birbirini destekledi. Tarih öncesi dönemleri adlandırırken kullanılan araç ve malzeme ölçütleri yardımcıdır, fakat toplumların bütün aşamaları zorunlu olarak aynı sırayla yaşadığını kanıtlamaz. Göç ve ticaret, bir topluluğun başka birinden yeni teknik öğrenmesini sağlayabilir; arkeolojik bulgular bu temaslarla birlikte yorumlanır.`, 'process', [['Ürün fazlası','Depolama imkânı'],['Uzmanlaşma','Farklı üretim faaliyetleri'],['Değiş tokuş','Topluluklar arası ilişki'],['Teknik aktarımı','Göç ve ticaretle öğrenme']], 'Maddi bulgu, geçim ve etkileşim ilişkileri içinde anlam kazanır.'));

  R('tar-16','İlk Çağ uygarlıklarını yerleri, kurumları ve kültürel katkılarıyla bir arada tanı.',
    B('Yazının farklı toplumlardaki rolü',`Mezopotamya’da Sümerler çivi yazısıyla, Asurlar ise ticaret ağlarıyla öne çıkar. Asurlu tüccarların Anadolu’daki karumları yalnız mal taşınan noktalar değil, yazının yayılmasını da destekleyen merkezlerdi. Anadolu’da Hititlerin anal adı verilen yıllıkları yönetim faaliyetlerini kayda geçiriyordu. Bu örnekler yazının tek işleve sahip olmadığını gösterir: kayıt, ticaret ve yönetim birbirine bağlanabilir. Bir uygarlığı belirli katkısıyla tanımak yararlıdır; ancak yalnız o faaliyetle uğraştığını düşünmek yanlıştır. Haritada Mezopotamya ile Anadolu arasındaki yakınlık da bu etkileşimi anlamaya yardımcı olur.`, 'process', [['Sümerler','Çivi yazısı ve kayıt'],['Asur karumları','Ticaretle yazı aktarımı'],['Hitit analları','Yönetim faaliyetlerinin kaydı'],['Etkileşim','Ekonomik ve kültürel ağ']], 'Bir araç olan yazı, farklı toplumsal ihtiyaçlarda kullanılabilir.'),
    B('Ticaret, takvim ve alfabe',`Batı Anadolu’daki Lidyalılar madenî paranın kullanımı ve ticaretle ilişkilidir. Nil çevresindeki Mısır uygarlığında güneş takvimi, matematik ve mimari önemli çalışma alanlarıdır. Doğu Akdeniz’de Fenikeliler deniz ticareti ve geliştirdikleri alfabe sayesinde kültürel aktarımda etkili olmuştur. Katkıları coğrafyayla birlikte yerleştirdiğinde isimler soyut bir liste olmaktan çıkar. Para değiş tokuşu, takvim zamanın düzenlenmesini, alfabe yazılı iletişimi kolaylaştırır. Bu araçların farklı toplumlara aktarılması, uygarlıkların birbirinden bütünüyle bağımsız gelişmediğini gösterir; kültürler karşılaşmalarla yeni biçimler kazanabilir.`, 'compare', [['Lidya','Para ve ticaret'],['Mısır','Güneş takvimi ve bilimsel birikim'],['Fenike','Deniz ticareti ve alfabe'],['Ortak sonuç','İletişim ve kültürel aktarım']], 'Katkıyı ezberlerken hangi ihtiyaca hizmet ettiğini de sor.'));

  R('cog-01','Coğrafya, doğayı ve insanı ayrı listeler olarak değil etkileşim içindeki bir ortam olarak inceler.',
    B('Doğal ortamın parçaları birlikte çalışır',`Atmosfer havayı, hidrosfer suları, litosfer taş küreyi, biyosfer canlıları kapsayan kavramlardır. Bunlar birbirinden duvarlarla ayrılmış alanlar değildir. Yağış toprağa ulaşır, bir bölümü sızar, bitkiler suyu kullanır ve terlemeyle atmosfere geri verir. Böylece tek bir orman örneğinde dört ortamın ilişkisini görebilirsin. Coğrafi inceleme, bir unsurun yalnız adını belirlemekle kalmaz; nerede bulunduğunu, hangi koşullarda geliştiğini ve diğer unsurları nasıl etkilediğini araştırır. Haritada dağılışı görmek, bu ilişkileri açıklamak için başlangıç sağlar.`, 'cycle', [['Atmosfer','Yağış ve hava koşulları'],['Hidrosfer','Suyun hareketi'],['Litosfer','Zemin ve toprak'],['Biyosfer','Canlıların suyu kullanması']], 'Doğal ortamın parçaları aynı süreç içinde birbirini etkiler.'),
    B('İnsan doğayı hem kullanır hem değiştirir',`İnsanlar yerleşme, tarım, ulaşım ve enerji üretiminde doğal koşullardan yararlanır. Dağlık arazi yol yapımını zorlaştırabilir; tünel yapımı bu engelin etkisini azaltabilir. Baraj suyu depolar ve enerji sağlayabilir, fakat akarsu düzenini ve çevredeki yerleşmeleri de değiştirebilir. Dolayısıyla etkileşim tek yönlü değildir. Aynı doğal ortamda yaşayan toplumların teknoloji ve ekonomik imkânlarının farklı olması, çevreden yararlanma biçimini değiştirebilir. Bir soruda doğanın insana etkisini mi, insanın doğaya müdahalesini mi gösteren örnek istendiğini önce belirle.`, 'cause', [['Doğal koşul','Dağ, su ve iklim'],['İnsan ihtiyacı','Ulaşım, üretim ve yerleşme'],['Müdahale','Tünel, tarım alanı veya baraj'],['Yeni etki','Çevrenin ve kullanımın değişmesi']], 'Teknoloji etkileşimi değiştirir; doğal koşulların bütün etkilerini ortadan kaldırmaz.'));

  R('cog-02','Gün içindeki değişimlerle yıl içindeki değişimlerin farklı nedenlerini gör.',
    B('Küresel şekil ve günlük dönüş',`Dünya’nın küresel biçimi nedeniyle Güneş ışınlarının düşme açısı enleme göre değişir. Bu durum genel sıcaklık dağılışının temel etkenlerinden biridir; her sıcaklık farkını tek başına açıklamaz. Dünya kendi ekseni çevresinde dönerken aynı yer sırayla aydınlık ve karanlık bölgede kalır. Gece ile gündüzün ardalanması ve Güneş’in gün içindeki görünür hareketi bu dönüşle ilişkilidir. Bir çubuğun gölgesinin gün içinde yön ve boy değiştirmesi de Güneş’in görünen konumunun değişmesinden kaynaklanır; gölgenin kendisi Dünya’yı döndürmez.`, 'process', [['Küresel şekil','Farklı düşme açıları'],['Günlük dönüş','Aydınlık ve karanlık bölgeler'],['Görünür hareket','Güneş’in gün içindeki konumu'],['Gölge','Yön ve uzunluk değişimi']], 'Aynı gözlemi açıklarken sebebi ve görünen sonucu ayır.'),
    B('Mevsimleri uzaklıkla açıklama',`Dünya’nın Güneş çevresindeki dolanımı ve eksen eğikliği birlikte, yıl boyunca ışınların geliş açısını ve gündüz süresini değiştirir. Kuzey Yarım Küre’de haziranda daha uzun gündüzler ve daha büyük geliş açıları ısınmayı desteklerken Güney Yarım Küre’de ters koşullar yaşanır. Bu karşıtlık, mevsimlerin yalnız Güneş’e uzaklıkla açıklanamayacağını gösterir. Ekinokslarda ışınlar Ekvator’a dik gelir ve gece-gündüz yaklaşık eşitlenir. Gündönümlerinde ise yarım küreler arasındaki gündüz süresi farkı belirginleşir; kutup daireleri çevresindeki özel koşullar da bunun sonucudur.`, 'cycle', [['Mart ekinoksu','Işınlar Ekvator’a dik'],['Haziran gündönümü','Kuzeyde en uzun gündüz'],['Eylül ekinoksu','Yeniden yaklaşık eşit süreler'],['Aralık gündönümü','Kuzeyde en uzun gece']], 'Yıllık değişimin mekanizması: eksen eğikliği, dolanım, açı ve süre.'));

  R('cog-03','Koordinat sisteminde enlem ve boylam farklı bilgileri taşır; konum yorumunda bunları karıştırma.',
    B('Paralel, meridyen ve yerel saat',`Paraleller Ekvator’a açısal uzaklığı gösteren enlemleri, meridyenler başlangıç meridyenine göre doğu-batı konumunu gösteren boylamları tanımlar. Enlem, Güneş ışınlarının geliş açısı ve gece-gündüz farkı gibi sonuçlarla ilişkilidir. Boylam ise yerel saat farkını hesaplamayı sağlar. Dünya yirmi dört saatte üç yüz altmış derece döndüğü için bir derece boylam dört dakikaya karşılık gelir. Doğudaki yerler Güneş’i daha önce gördüğünden yerel saatleri ileridir. Aynı ulusal saati kullanmaları, şehirlerin yerel saatlerinin de aynı olduğunu göstermez.`, 'compare', [['Enlem','Kuzey–güney ve düşme açısı'],['Boylam','Doğu–batı ve yerel saat'],['1° boylam','4 dakika zaman farkı'],['Doğu yönü','Yerel saat ileridir']], 'Yerel saat gök hareketine, ulusal saat ortak kullanım kararına dayanır.'),
    B('Türkiye’nin iki tür konumu',`Türkiye yaklaşık otuz altı ile kırk iki derece kuzey enlemleri arasında, dönencelerin kuzeyinde bulunur. Bu mutlak konum, Güneş ışınlarının yatay yüzeye yıl boyunca dik gelmemesi ve orta kuşak özellikleriyle ilişkilidir. Boğazlara sahip olması, denizler arasında bulunması, komşuları ve yükseltisi ise göreceli konum kapsamında değerlendirilir. Örneğin kıyı ile iç kesim arasındaki sıcaklık farkını yalnız enlemle açıklamak yanlış olabilir. Önce iki yerin ortak özelliklerini belirle; sonra denize uzaklık ve yükselti gibi farklı koşulları karşılaştır.`, 'compare', [['Mutlak konum','Enlem ve boylam'],['Göreceli konum','Deniz, boğaz, komşu ve yollar'],['Doğal fark','Yükselti ve denize uzaklık'],['Yorum','Ortak etkeni ele, farklı etkeni ara']], 'Konum tek bir sayı veya tek bir sonuç değildir.'));

  R('cog-04','Haritayı okumak, küçültme oranını ve sembollerin neyi temsil ettiğini birlikte anlamaktır.',
    B('Harita gerçeğin seçilmiş modelidir',`Harita bir alanın kuş bakışı görünümünü belirli oranda küçültüp düzlem üzerinde gösterir. Başlık hangi konunun ele alındığını, lejant renk ve işaretlerin anlamını açıklar. Fiziki haritada yeşil bir alanın mutlaka orman olduğunu söyleyemezsin; renk yükselti basamağını gösteriyor olabilir. Aynı bölgenin nüfus, yağış veya ulaşım haritaları farklı bilgiler taşır. Bu nedenle bir sembolü günlük çağrışımıyla değil, haritanın açıklamasıyla yorumla. Ölçek ve yön bilgisi de konumlar arasındaki gerçek ilişkileri kurmak için gereklidir.`, 'hierarchy', [['Başlık','Gösterilen konu'],['Lejant','Sembol ve renklerin anlamı'],['Ölçek','Gerçekle küçültme ilişkisi'],['Yön','Konumları karşılaştırma']], 'Haritanın ne anlattığını öğrenmeden işaretlerin ne anlama geldiğine karar verme.'),
    B('Ölçeğin paydası ve ayrıntı',`Kesir ölçekte payda küçüldükçe harita ölçeği büyür. Aynı kâğıtta daha dar alan gösterilir, ayrıntı artar. Bir bölgenin mahallesini incelemek için ülke haritasından daha büyük ölçek gerekir. Uzunluk hesabında harita uzunluğunu ölçeğin paydasıyla çarpar ve birimleri dönüştürürsün. Bir bölü yüz bin ölçekte bir santimetre, gerçekte bir kilometredir. Alan hesabında küçültme iki boyutta olduğundan ölçeğin karesi devreye girer. Uzunluk için kullandığın dönüşümü doğrudan alana uygulamak, sonucun çok farklı çıkmasına yol açar.`, 'process', [['Payda küçülür','Ölçek büyür'],['Alan daralır','Ayrıntı artar'],['Uzunluk','Tek boyutlu küçültme'],['Alan hesabı','İki boyutta küçültme']], 'Büyük ölçek daha büyük alan değil, daha büyük gösterim ve ayrıntı demektir.'));

  R('cog-05','Atmosfer koşullarını incelerken günlük gözlemle uzun yılların düzenini ayır.',
    B('Hava durumu ile iklim neden farklıdır?',`Atmosfer, Dünya’yı çevreleyen gaz örtüsüdür; hava olaylarının önemli bölümü en alt katmanda gerçekleşir. Bugün yağmur yağması veya yarın sıcaklığın düşmesi hava durumuna ilişkin kısa süreli bilgidir. İklim ise bir alanın uzun yıllar boyunca gösterdiği genel atmosfer koşullarını anlatır. Tek bir yağmurlu yaz günü, yazları genellikle kurak olan iklimi tek başına değiştirmez. Bir iklimi değerlendirirken ortalama sıcaklığı, yağış miktarını ve bunların yıl içindeki dağılışını birlikte incelemek gerekir. Ortalama, her günün aynı olduğu anlamına da gelmez.`, 'compare', [['Atmosfer','Gaz örtüsü ve hava olayları'],['Hava durumu','Kısa süreli koşul'],['İklim','Uzun yılların genel düzeni'],['Değişkenlik','Ortalama çevresindeki farklılıklar']], 'Tek olay ile uzun süreli düzen farklı inceleme ölçekleridir.'),
    B('Aynı enlemde sıcaklık neden farklı olabilir?',`Enlem ışınların geliş açısını etkiler; fakat yükselti, denize uzaklık, bakı, rüzgâr ve akıntılar sıcaklık dağılışını değiştirir. Denizler karalara göre geç ısınıp geç soğuduğu için kıyılarda yıllık sıcaklık farkı genellikle daha küçüktür. Troposferde yükseldikçe sıcaklık genel olarak azalır. Türkiye’de güneye bakan yamaçlar çoğunlukla daha fazla güneş enerjisi alır; buna bakı etkisi denir. İki merkezi karşılaştırırken yalnız haritadaki kuzey-güney sırasına bakma. Ortak enleme rağmen farklı sıcaklık varsa diğer koşulları özellikle sorgula.`, 'cause', [['Enlem','Işınların geliş açısı'],['Yükselti','Genel soğuma etkisi'],['Denizellik','Sıcaklık farkının azalması'],['Bakı','Yamacın enerji alma durumu']], 'Sıcaklık dağılışında birden fazla etken aynı anda çalışır.'));

  R('cog-06','Yağış mekanizmasını anlamak için havanın neden yükseldiğini ve yükselirken nasıl değiştiğini izle.',
    B('Basınç farkından yükselen havaya',`Atmosfer basıncı, üzerimizdeki hava sütununun ağırlığının birim alana etkisiyle ilişkilidir. Bir yerdeki basınç çevresinden düşükse yüzeye yakın hava merkeze yönelir; yüksekse çevreye dağılır. Alçak basınç alanlarında yükselici hareketler yaygındır. Yükselen hava daha düşük dış basınçla karşılaştıkça genişler ve soğur. Bu soğuma havayı doygunluğa yaklaştırabilir. Ancak yalnız yükselme bulunması her durumda yağış garantisi değildir; başlangıçtaki nem ve soğuma miktarı da önemlidir. Basıncın mutlak değerinden önce çevresiyle farkına bakmak gerekir.`, 'process', [['Basınç farkı','Yatay hava hareketi'],['Yükselme','Daha düşük dış basınç'],['Genişleme','Havanın soğuması'],['Doygunluğa yaklaşma','Nem koşullarının önemi']], 'Yağış için yükselme kadar nem ve yeterli soğuma da gerekir.'),
    B('Nem ve üç temel yağış mekanizması',`Mutlak nem havadaki su buharı miktarını, bağıl nem ise mevcut sıcaklıkta doygunluğa yakınlığı anlatır. Su buharı miktarı aynı kalırken hava soğursa bağıl nem artabilir. Nemli havanın dağ yamacında yükselmesi orografik, yüzeyin güçlü ısınmasıyla yükselmesi konveksiyonel yağışı destekler. Farklı özellikteki hava kütlelerinin karşılaşması cephe yağışıyla ilişkilidir. Çiy ise soğuk yüzey üzerindeki yoğuşmadır; yamaç boyunca yükselen havanın yağışından farklı oluşur. Bir soruda suyun yalnız varlığını değil, hangi mekanizmayla yoğunlaştığını takip et.`, 'compare', [['Yamaç','Dağ engeliyle yükselme'],['Konveksiyon','Isınmayla yükselme'],['Cephe','Hava kütlelerinin karşılaşması'],['Çiy','Soğuk yüzeyde yoğuşma']], 'Aynı su buharı, farklı koşullarda farklı yoğuşma ürünleri oluşturabilir.'));

  R('cog-07','İklim tipini sıcaklık ve yağışın birlikte çizdiği yıllık düzenden çıkar.',
    B('Grafikte iki değişkeni birlikte oku',`İklim grafiğinde sıcaklık çizgisi yılın sıcak ve serin dönemlerini, sütunlar yağışın mevsimlere dağılışını gösterir. Önce sıcaklığın en yüksek olduğu aylardan yarım küreyi düşün; ardından yıllık sıcaklık farkına ve kurak mevsime bak. Ekvatoral iklimde yıl boyunca sıcaklık yüksek ve yağış boldur. Çöl ikliminde yağış çok azdır. Akdeniz iklimini ayırt eden önemli özellik yaz kuraklığıdır. Yalnız yıllık toplam yağışı bilmek yeterli değildir; aynı toplam, yıl içine farklı dağıldığında bitki ve tarım koşulları değişebilir.`, 'process', [['Sıcak aylar','Yarım küre ipucu'],['Sıcaklık farkı','Yıllık değişimin büyüklüğü'],['Yağış dağılışı','Kurak ve yağışlı mevsim'],['İklim yorumu','İki değişkenin ortak sonucu']], 'İklim, sıcaklık veya yağışın tek başına okunduğu bir etiket değildir.'),
    B('Türkiye’de bitki örtüsüne uzanan mekanizma',`Türkiye’de denize yakınlık, dağların uzanışı ve yükselti iklim çeşitliliğini artırır. Karadeniz kıyısındaki nemli koşullar orman gelişimini destekler; kıyıya paralel dağlar deniz etkisinin içeriye ulaşmasını sınırlar. Akdeniz kıyılarında yaz kuraklığına dayanıklı bitkiler belirgindir; maki, bu koşullarla ilişkili çalı topluluğudur. İç kesimlerde karasallık arttıkça sıcaklık farkı büyüyebilir, yağış ve yükseltiye göre bozkır veya çayır gibi topluluklar gelişebilir. Bitkiyi yalnız bölge adıyla ezberlemek yerine, su ve sıcaklık ihtiyacıyla iklim koşullarını eşleştir.`, 'cause', [['Deniz ve dağ','Nemin içeriye ulaşması'],['Sıcaklık ve yağış','Yetişme koşulları'],['Uyum','Kuraklığa veya soğuğa dayanma'],['Bitki örtüsü','Koşullara uygun topluluklar']], 'Doğal bitki örtüsü, uzun süreli çevre koşullarının göstergelerinden biridir.'));

  R('cog-08','Yerin iç enerjisi şekilleri oluşturur; yüzey süreçleri bunları aşındırır ve dönüştürür.',
    B('Levha hareketleri hangi sonuçları doğurur?',`Yer kabuğu ve üst mantonun katı bölümünü oluşturan levhalar birbirlerine göre hareket eder. Yaklaşma, uzaklaşma ve yanal hareketler farklı yer şekilleri ve tehlikelerle ilişkilidir. Orojenez dağ oluşumunu, epirojenez geniş alanların yavaş yükselip alçalmasını anlatır. Volkanizmada magma yüzeye veya kabuğun içine ilerler; depremde ise biriken enerji ani biçimde açığa çıkar. Türkiye’nin aktif levha kuşağında bulunması genç yer şekilleri ve deprem tehlikesiyle bağlantılıdır. Fakat fayın yerini bilmek, depremin kesin gününü bilmek anlamına gelmez.`, 'compare', [['Orojenez','Dağ oluşumu'],['Epirojenez','Geniş alanlarda düşey hareket'],['Volkanizma','Magma hareketi'],['Deprem','Birikmiş enerjinin ani boşalması']], 'İç kuvvetler aynı enerji kaynağıyla ilişkili olsa da aynı olayı anlatmaz.'),
    B('Kayaçlar nasıl birbirine dönüşür?',`Magma soğuyup katılaşınca püskürük kayaçlar oluşur; soğumanın yeri ve hızı yapıyı etkiler. Yüzeyde parçalanan malzemeler taşınıp birikir, uygun koşullarda tortul kayaçlara dönüşebilir. Var olan kayaçların sıcaklık ve basınç etkisiyle değişmesi başkalaşımdır; kalkerin mermere dönüşmesi örnektir. Daha derinde erime yeniden magma oluşturabilir. Bu döngü tek bir zorunlu sıra değildir: farklı kayaçlar aşınabilir, başkalaşabilir veya eriyebilir. Kayaç türünü yalnız bulunduğu yüksekliğe göre değil, oluşum sürecine göre belirlemek gerekir.`, 'cycle', [['Magma','Soğuma ve katılaşma'],['Püskürük kayaç','Aşınma ve parçalanma'],['Tortul kayaç','Birikme ve taşlaşma'],['Başkalaşım','Sıcaklık ve basınçla dönüşüm']], 'Oklar olası dönüşüm yollarını gösterir; her kayaç bütün aşamaları sırayla geçmez.'));

  R('cog-09','Yer şekli sorularında kuvveti, süreci ve gerekli ortamı birbirine bağla.',
    B('Parçalanma ile taşınma aynı şey değildir',`Kayaçların bulundukları yerde fiziksel olarak parçalanması veya kimyasal olarak çözünmesi, dış kuvvetlerin işleyebileceği malzemeyi hazırlar. Su, rüzgâr ve buz bu malzemeyi aşındırabilir, taşıyabilir ve uygun yerde biriktirebilir. Hangi etkenin baskın olduğu iklim, eğim, bitki örtüsü ve kayaç yapısına bağlıdır. Kurak ve seyrek bitkili alanda rüzgâr daha etkili olabilirken kalıcı buz bulunan yüksek kesimlerde buzul şekilleri gelişebilir. Bir yerde rüzgâr esmesi, bütün şekillerin rüzgâr tarafından yapıldığını göstermez; ortam koşullarını da kanıt olarak kullan.`, 'process', [['Çözülme','Kayaçların yerinde değişmesi'],['Aşındırma','Malzemenin koparılması'],['Taşıma','Malzemenin yer değiştirmesi'],['Birikme','Taşıma gücünün azalması']], 'Dış kuvvetler aynı anda her yerde aynı ölçüde etkili değildir.'),
    B('Şekli oluşturan mekanizmayı bul',`Akarsu vadisi aşındırmayla, delta ise taşınan alüvyonun kıyıda birikmesiyle gelişir. Güçlü dalga ve akıntılar malzemeyi uzaklaştırırsa her akarsu ağzında delta oluşmaz. Karstik mağara ve dolinlerde çözünebilen kayaç ile su etkileşimi önemlidir; traverten çözünmüş maddelerin çökelmesiyle oluşur. Kıyı falezi dalga aşındırması, kıyı oku ve tombolo birikmeyle ilişkilidir. Benzer biçimde kumul rüzgâr biriktirmesidir. Şeklin adını gördüğünde önce aşınma mı birikme mi olduğunu sor, ardından etkili kuvveti ve gerekli koşulu belirle.`, 'compare', [['Akarsu','Vadi aşındırma; delta biriktirme'],['Karst','Çözünme ve çökelme'],['Dalga','Falez ve kıyı birikimleri'],['Rüzgâr','Kumul gibi birikim şekilleri']], 'Aynı kuvvet hem aşındırma hem biriktirme yapabilir.'));

  R('cog-10','Su, toprak ve bitki ayrı ezberler değil birbirini besleyen doğal sistemlerdir.',
    B('Su döngüsü kullanılabilir suyu nasıl etkiler?',`Yüzeylerden buharlaşan ve bitkilerden terlemeyle çıkan su atmosfere katılır; yoğuşma ve yağışla yeryüzüne döner. Yağışın bir bölümü yüzeyden akar, bir bölümü zemine sızarak yer altı suyunu besler. Bu dolaşım suyun sürekli hareket ettiğini gösterir, fakat her yerde sınırsız temiz su bulunduğu anlamına gelmez. Kirlenme, aşırı çekim ve mevsimlik yağış farkları kullanılabilir kaynağı azaltabilir. Akarsuda debi geçen su miktarını, rejim yıl içindeki düzeni anlatır. Yüksek debi ile düzenli rejim aynı özellik değildir.`, 'cycle', [['Buharlaşma ve terleme','Atmosfere geçiş'],['Yoğuşma ve yağış','Yeryüzüne dönüş'],['Yüzey akışı','Akarsu ve göllere ulaşma'],['Sızma','Yer altı suyunu besleme']], 'Döngünün sürmesi, yerel temiz su ihtiyacının her koşulda karşılandığını göstermez.'),
    B('Toprak ile bitki karşılıklı destek sağlar',`Toprak; ana kaya, iklim, canlılar, yer şekilleri ve zamanın birlikte etkisiyle gelişir. Bitki artıkları organik madde sağlarken kökler toprağı tutar; toprak da bitkiye su ve mineral sunar. İklim ve bitki örtüsünün belirgin olduğu topraklar zonal, ana kaya veya drenaj gibi yerel koşulların baskın olduğu topraklar intrazonal grupta incelenir. Akarsuyun taşıyıp biriktirdiği alüvyon üzerinde gelişenler azonal örnektir. Taşınmış toprağın bütün özelliklerini bulunduğu yerin iklimine bağlamak bu nedenle yanlış sonuç verebilir; oluşum yolunu da araştırmalısın.`, 'cycle', [['Ana kaya ve iklim','Toprak oluşum koşulları'],['Toprak','Su ve mineral kaynağı'],['Bitki','Kök ve organik artık'],['Koruma','Toprağın tutulması ve humus']], 'Toprak, hem oluştuğu koşulları hem taşınma geçmişini yansıtabilir.'));

  R('cog-11','Nüfusu saymak, nerede toplandığını ve hangi yaşlardan oluştuğunu anlamakla tamamlanır.',
    B('Nüfus miktarı ve yoğunluğu',`Nüfus, belirli sınırlar içinde belirli zamanda yaşayan insan sayısıdır. Aritmetik yoğunluk bu sayının toplam yüz ölçümüne bölünmesiyle bulunur. Ancak ortalama yoğunluk, insanların ülkenin her yerine eşit dağıldığını göstermez. Su, iklim ve uygun arazi doğal çekicilik oluşturabilir; sanayi, ticaret ve ulaşım da nüfusu belirli merkezlerde toplayabilir. Aynı ülkenin yüksek dağları ile kıyı ovaları farklı yoğunluklara sahip olabilir. Haritadaki dağılışı açıklarken hem doğal hem beşerî etkenleri değerlendirmek, yalnız toplam nüfusa bakmaktan daha güçlü sonuç verir.`, 'cause', [['Doğal koşullar','Su, iklim ve yer şekilleri'],['Ekonomik koşullar','İş ve ulaşım imkânları'],['Dağılış','Nüfusun yoğunlaştığı alanlar'],['Yoğunluk','Toplamın alana oranı']], 'Bir ortalama sayı, ülke içindeki bütün farklılıkları göstermez.'),
    B('Piramidin tabanı, ortası ve üstü',`Nüfus piramidi yaş gruplarını ve cinsiyet dağılımını birlikte gösterir. Geniş taban çocuk nüfus payının yüksekliğine, daralan taban yeni kuşakların küçülmesine işaret edebilir. Üst kesimin genişlemesi yaşlı nüfus payının arttığını düşündürür. Orta yaşlarda belirgin bir şişkinlik geçmiş doğum dalgaları veya çalışma çağındaki göçlerle ilişkili olabilir. Yalnız tabanın daralmasına bakarak toplam nüfusun kesin azaldığını söyleme; doğum, ölüm ve göç birlikte etkilidir. Piramidin sayı mı oran mı gösterdiğini de kontrol et; farklı ölçekler görsel büyüklüğü değiştirebilir.`, 'hierarchy', [['Taban','Çocuk yaş grupları'],['Orta','Çalışma çağındaki gruplar'],['Üst','Yaşlı nüfus'],['Ölçek','Sayı veya oran bilgisi']], 'Piramidi yorumlarken şekille birlikte eksen ve açıklamaları da oku.'));

  R('cog-12','Göç birden fazla ölçüte göre sınıflanır; nüfus hesabındaki etkisi sınırın nerede çizildiğine bağlıdır.',
    B('Aynı göçün birden fazla niteliği olabilir',`Bir kişinin eğitim için başka ülkeye geçici olarak gitmesi hem dış göç hem süre bakımından geçici göçtür. Ülke içindeki mevsimlik tarım işçiliği ise iç ve geçici göç olabilir. Savaş veya afet zorunlu göçe yol açabilirken iş ve eğitim arayışı gönüllü hareketi destekleyebilir. Bu sınıflamalar birbirini dışlamaz; farklı sorulara cevap verir. Çıkılan yerdeki işsizlik itici, gidilen yerdeki iş imkânı çekici etkendir. Göçü yalnız hedef merkezin özelliğiyle değil, iki tarafın koşulları arasındaki ilişkiyle açıklamak gerekir.`, 'compare', [['Sınır','İç veya dış göç'],['Süre','Geçici veya sürekli'],['İstek','Gönüllü veya zorunlu'],['Neden','İtici ve çekici koşullar']], 'Sınıflandırma ölçütleri farklıdır; tek hareket birden çok gruba girer.'),
    B('Doğal artış ile gerçek değişim',`Doğal nüfus artışı doğumlar ile ölümler arasındaki farktır. Gerçek nüfus değişimini bulurken gelen ve giden göçün farkını da eklersin. Örneğin doğum-ölüm farkı kırk bin, net göç eksi altmış binse toplam nüfus yirmi bin azalır. İç göç ülkenin toplamını doğrudan değiştirmez; aynı insanlar ülke içinde yer değiştirir. Fakat göç veren ve alan illerin nüfusunu, yaş yapısını ve hizmet ihtiyacını etkiler. Dış göç ise ülke sınırını geçtiği için ülke toplamını da doğrudan değiştirebilir.`, 'process', [['Doğum − ölüm','Doğal artış'],['Gelen − giden','Net göç'],['İki farkın toplamı','Gerçek nüfus değişimi'],['Seçilen sınır','İl veya ülke ölçeği']], 'Nüfus hesabında önce hangi alanın toplamını hesapladığını belirle.'));

  R('cog-13','Ekonomik faaliyetleri üretim zincirindeki işlevleriyle, ulaşımı da bu zincirin bağlantısıyla öğren.',
    B('Aynı ürün üç farklı sektörde bulunabilir',`Doğadan doğrudan kaynak elde etmek birincil faaliyettir: tarım, balıkçılık ve madencilik bu gruptadır. Ham maddeyi işleyip ürüne dönüştürmek ikincil, hizmet sunmak üçüncül faaliyettir. Buğday yetiştiren çiftçi, un üreten fabrika ve unu satan market aynı zincirde farklı işler yapar. Bu yüzden sektör ürünün adıyla değil, yapılan işin niteliğiyle belirlenir. Bilgi üretimine dayalı faaliyetler dördüncül, üst düzey karar ve yönetim beşincil olarak da sınıflandırılır. Bir mesleği değerlendirirken günlük adından önce hangi işlevi yerine getirdiğini sor.`, 'process', [['Birincil','Doğadan kaynak elde etme'],['İkincil','Ham maddeyi işleme'],['Üçüncül','Ticaret ve diğer hizmetler'],['Bilgi ve yönetim','Dördüncül ve beşincil işler']], 'Ürün aynı kalsa bile üretim zincirindeki görev değişebilir.'),
    B('Ulaşım neden üretimin bir parçasıdır?',`Üretilen malın tüketiciye ulaşabilmesi için taşıma, depolama ve ticaret ağları gerekir. Ulaşım imkânlarının gelişmesi pazara erişimi kolaylaştırabilir ve maliyeti düşürebilir. Dağlık alanlarda yol yapımı zorlaşırken geçitler, limanlar ve boğazlar stratejik düğümler oluşturur. Süveyş ve Panama gibi kanallar bazı deniz yollarını kısaltır. Ancak en kısa yol her koşulda tek tercih değildir; güvenlik, kapasite ve taşıma türü de önemlidir. Haritada yalnız çizginin uzunluğuna değil, hangi üretim ve tüketim merkezlerini birbirine bağladığına da bak.`, 'cause', [['Üretim merkezi','Malın kaynağı'],['Ulaşım ağı','Taşıma ve bağlantı'],['Düğüm noktası','Liman, boğaz veya kanal'],['Pazar','Tüketiciye erişim']], 'Ulaşım, yerler arasındaki ekonomik ilişkiyi kuran ağdır.'));

  R('cog-14','Doğal tehlike ile afet kaybını ayır; aynı olay farklı yerlerde farklı sonuç doğurabilir.',
    B('Tehlike, maruziyet ve kırılganlık',`Deprem veya şiddetli yağış doğal bir süreçtir; toplumda ciddi kayıp ve kesintiye yol açtığında afet niteliği kazanır. Tehlikeli alanda insan ve yapı bulunması maruziyeti, bu yapıların dayanıksızlığı veya hazırlığın yetersizliği kırılganlığı artırır. Bu nedenle benzer büyüklükte iki deprem aynı kaybı oluşturmak zorunda değildir. Uygun yer seçimi, mühendislik, altyapı ve eğitim kayıpları azaltabilir. Doğa olayının oluşmasını bütünüyle önleyememek, zarar karşısında hiçbir şey yapılamayacağı anlamına gelmez; riskin insanla ilgili parçaları üzerinde çalışılabilir.`, 'cause', [['Tehlike','Olayın doğal özellikleri'],['Maruziyet','İnsan ve yapıların konumu'],['Kırılganlık','Dayanıklılık ve hazırlık'],['Kayıp','Bu etkenlerin ortak sonucu']], 'Afet etkisini yalnız olayın büyüklüğüne indirgeme.'),
    B('Süreç farklıysa önlem de farklılaşır',`Heyelan, zemin veya kaya kütlesinin yamaç boyunca hareketidir; eğim, suya doygunluk ve zemin yapısı önemlidir. Erozyonda ise yüzey toprağı su veya rüzgârla aşınıp taşınır; bitki örtüsünün kaybı süreci hızlandırabilir. Selde kısa sürede gelen suyun akış ve tahliye koşulları belirleyicidir. Dere yatağına yapılaşma kayıpları büyütebilir. Çığ için eğimli kar örtüsü, orman yangını için yanıcı madde ve uygun hava koşulları birlikte değerlendirilir. Her afete tek önlem önermek yerine, oluşum mekanizmasını ve yerel koşulları belirlemek gerekir.`, 'compare', [['Heyelan','Kütlenin yamaçta hareketi'],['Erozyon','Yüzey toprağının taşınması'],['Sel','Suyun taşması ve hızlı akış'],['Önlem','Mekanizmaya uygun yerel çözüm']], 'Benzer görünen zararlar farklı süreçlerden doğabilir.'));

  R('cog-15','Rüzgârı açıklarken basıncın oluşum nedenini, yönünü ve hızını ayrı düşün.',
    B('Yüksek basınç her zaman soğuk değildir',`Havanın ısınması ve yükselmesi termik alçak basıncı, soğuması ve alçalması termik yüksek basıncı destekleyebilir. Ancak genel atmosfer dolaşımındaki hava hareketleri de dinamik basınç alanları oluşturur. Bu nedenle bir alanın yalnız yüksek basınçlı olduğunu bilmek, sıcaklığını kesin belirlemek için yeterli değildir. Yüzeye yakın rüzgâr yüksek basınçtan alçak basınca yönelme eğilimindedir. Basınç farkı ve merkezler arasındaki uzaklık hız üzerinde etkilidir. Dünya’nın dönüşü ile yüzey koşulları ise hareketin gerçek yönünü basit düz çizgiden saptırabilir.`, 'compare', [['Termik','Isınma veya soğuma etkisi'],['Dinamik','Genel dolaşımdaki hareket'],['Basınç farkı','Rüzgârın başlangıç nedeni'],['Sapma ve sürtünme','Gerçek yönün değişmesi']], 'Basıncın adı, sıcaklığın tek başına yeterli göstergesi değildir.'),
    B('Günlük ve mevsimlik ısınma farkları',`Karalar denizlerden hızlı ısınıp hızlı soğur. Gündüz kara daha çok ısınınca kıyıda denizden karaya meltem gelişebilir; gece fark tersine dönünce karadan denize eser. Musonlarda benzer kara-deniz farkı mevsimlik ölçekte belirginleşir ve yön değiştirir. Sürekli rüzgârlar ise genel basınç kuşaklarıyla ilişkilidir; alizeler ve batı rüzgârları bu gruptadır. Bu türleri yalnız yön adlarıyla ezberlemek yerine farkın hangi zaman ölçeğinde oluştuğunu düşün. Yer şekilleri ve yerel koşullar da gözlenen yönü etkileyebilir; ideal şema her kıyının ayrıntısını göstermez.`, 'cycle', [['Gündüz meltemi','Denizden karaya'],['Gece meltemi','Karadan denize'],['Muson','Mevsimlik yön değişimi'],['Sürekli rüzgâr','Genel basınç kuşakları']], 'Aynı ısınma farkı ilkesi, farklı zaman ve alan ölçeklerinde etkili olabilir.'));

  R('cog-16','Yerleşmenin yeri, dokusu ve işlevi ayrı özelliklerdir; bölge ise seçilen ortak ölçüte dayanır.',
    B('Evlerin dağılışı hangi koşulları yansıtır?',`Yerleşmelerin kurulmasında su, üretim imkânı, iklim, arazi ve ulaşım önemlidir. Evlerin birbirine yakın olması toplu, aralıklı yayılması dağınık dokuyu anlatır. Su kaynaklarının yaygın ve arazinin parçalı olduğu yerlerde dağınık doku desteklenebilir; sınırlı su çevresinde toplu yerleşme gelişebilir. Ancak mülkiyet ve kültürel alışkanlıklar da etkili olduğundan tek doğal özellikten kesin sonuç çıkarma. Meskenlerde kullanılan taş, ahşap veya kerpiç yerel malzemeyle ilişkili olabilir. Teknoloji ve ekonomik imkânlar geliştikçe malzeme seçimi yalnız yakın çevreye bağlı kalmayabilir.`, 'cause', [['Yer seçimi','Su ve geçim imkânı'],['Doku','Evlerin toplu veya dağınık oluşu'],['Mesken','Malzeme ve yapı özellikleri'],['Beşerî etken','Mülkiyet, kültür ve teknoloji']], 'Yerleşmenin farklı özellikleri aynı nedenden etkilenebilir ama aynı şeyi anlatmaz.'),
    B('Bölge sınırını ölçüt oluşturur',`İklim veya yer şekli benzerliğine göre çizilen alan doğal bölgedir. Sanayi ve nüfus gibi insan faaliyetlerine göre belirlenenler beşerî bölgedir. Bir hastanenin hizmet verdiği çevre ise merkezle bağlantı esasına dayanan işlevsel bölgedir. Bu sınırlar ülke veya il sınırlarıyla zorunlu olarak çakışmaz. Aynı şehir sanayi, liman ve eğitim işlevlerini birlikte taşıyabilir; farklı ölçütlerle farklı bölgelere dâhil olur. Zaman içinde hizmet ağı veya ekonomik yapı değişince bazı bölge sınırları da değişebilir; bölgeyi değişmez tek bir kalıp gibi düşünme.`, 'compare', [['Doğal bölge','İklim veya yer şekli'],['Beşerî bölge','Nüfus ve ekonomik faaliyet'],['İşlevsel bölge','Bir merkezin bağlantı ve hizmet alanı'],['Sınır','Ölçüte ve zamana göre değişim']], 'Bir yerin birden fazla bölgeye girmesi çelişki değil, farklı ölçütlerin sonucudur.'));

  R('cog-17','İzohipsler yükseltiyi, ölçek yatay uzaklığı verir; kesit ve eğim ikisini birleştirir.',
    B('Çizgilerden yüzey profiline',`İzohips, aynı yükseltideki noktaları birleştiren çizgidir. Aynı haritada ardışık çizgiler arasındaki yükselti farkı sabittir. Çizgilerin sıklaşması, kısa yatay uzaklıkta daha çok yükselti değiştiğini ve eğimin arttığını gösterir. Bir kesit çizgisi boyunca sırasıyla yüz, iki yüz, üç yüz, iki yüz ve yüz metre eğrilerini geçiyorsan önce yükselip sonra alçalırsın. Başlangıçla bitişin aynı yükseltide olması aradaki yolun düz olduğunu göstermez. En içteki çizginin değeri de gerçek zirvenin kesin yüksekliği olmayabilir; ek yükseklik bilgisi gerekir.`, 'process', [['Başlangıç','Kesit çizgisinin ilk yükseltisi'],['Yükselme','Daha yüksek eğrilerin geçilmesi'],['Yüksek kesim','En iç çizgi ve olası zirve'],['Alçalma','Daha düşük eğrilere dönüş']], 'Kesit, haritadaki sıranın düşey görünüşe çevrilmesidir.'),
    B('Ortalama eğimi birimlerle hesapla',`Önce iki noktanın yükselti farkını bul, sonra harita uzaklığını ölçekle gerçek yatay uzaklığa çevir. Yüzde eğim, yükselti farkının yatay uzaklığa oranının yüzle çarpımıdır. Örneğin dört yüz metre yükselti farkı iki kilometre yatay uzaklıkta gerçekleşiyorsa birimleri eşitleyip dört yüzü iki bine bölersin; sonuç yüzde yirmidir. Yürüyüş yolunun uzunluğunu yatay uzaklık yerine kullanma. Yalnız başlangıç ve bitişten hesaplanan bu değer ortalamadır; rota üzerindeki her küçük kesimin aynı eğime sahip olduğunu göstermez.`, 'process', [['Yükselti farkı','Düşey değişim'],['Ölçek dönüşümü','Gerçek yatay uzaklık'],['Birim eşitleme','Metre ile metre'],['Oran × 100','Ortalama yüzde eğim']], 'Doğru formül, yanlış birimle kullanıldığında doğru sonuç vermez.'));

  R('fiz-tyt-01','Fizikte bir büyüklüğü tanımlamak, doğru birim ve gerektiğinde yön bilgisi seçmeyi gerektirir.',
    B('Ölçüm sonucu neden birimle anlam kazanır?',`Bir masanın uzunluğunu yalnız iki diye söylemek yeterli değildir; iki metre ile iki santimetre farklı sonuçlardır. Ölçüm, seçilen birimle karşılaştırmadır ve kullanılan aracın duyarlılığı sonucun hassasiyetini sınırlar. SI sisteminde uzunluk metre, kütle kilogram, zaman saniye ile ifade edilir. Kuvvet gibi türetilmiş büyüklükler temel birimlerin birleşiminden oluşur. Newtonun kilogram çarpı metre bölü saniyenin karesi olması, kuvvetin kütle ve ivmeyle ilişkisini de gösterir. Bir denklemde uyumsuz birimleri toplamak, fiziksel anlam taşımayan bir sonuç üretir.`, 'hierarchy', [['Ölçüm','Sayı ile birimin birlikteliği'],['Temel büyüklük','Uzunluk, kütle ve zaman'],['Türetilmiş büyüklük','Temel birimlerin birleşimi'],['Birim kontrolü','Denklemin fiziksel tutarlılığı']], 'Birim, sonuca sonradan eklenen süs değil ölçülen büyüklüğün parçasıdır.'),
    B('Yol, yer değiştirme, sürat ve hız',`Bir kişi önce kırk metre doğuya, sonra otuz metre batıya gidiyorsa toplam yetmiş metre yol alır; başlangıcına göre on metre doğudadır. Hareket on saniye sürerse ortalama sürati yedi metre bölü saniye, ortalama hızı doğuya bir metre bölü saniyedir. Bu fark, skaler ve vektörel büyüklüklerin ayrımını somutlaştırır. Yol ve süratte yön gerekmez; yer değiştirme ve hızda gerekir. Gidip başlangıca dönmek ortalama hızı sıfırlayabilir, fakat hareket boyunca alınan yolu ve harcanan zamanı ortadan kaldırmaz.`, 'compare', [['Gidiş ve dönüş','40 m doğu, 30 m batı'],['Yol','70 m'],['Yer değiştirme','10 m doğu'],['10 saniyede','Sürat 7; hız doğuya 1 m/s']], 'Aynı hareket farklı büyüklüklerle farklı yönlerden tanımlanır.'));

  R('fiz-tyt-02','Miktara bağlı özellikleri, maddenin cinsi ve koşullarına bağlı olanlardan ayır.',
    B('Özkütle neden parçalamayla değişmez?',`Özkütle, kütlenin hacme oranıdır. Aynı sıcaklık ve basınçtaki homojen bir örnekte madde miktarı arttıkça kütle ile hacim aynı oranda artar. İki yüz gramlık, yüz santimetreküplük bir parçanın özkütlesi iki gram bölü santimetreküptür. İkiye ayrıldığında her parçanın yüz gram ve elli santimetreküp olması oranı değiştirmez. Buna karşılık ısınma hacmi değiştirirse özkütle değişebilir. Bu yüzden özkütlenin ayırt edici oluşunu bütün koşullarda hiç değişmez olmakla karıştırma; karşılaştırmanın sıcaklık ve basınç koşullarını mutlaka incele.`, 'compare', [['İlk örnek','200 g / 100 cm³'],['Yarım örnek','100 g / 50 cm³'],['Oran','İkisinde de 2 g/cm³'],['Koşul değişimi','Hacim değişirse oran değişebilir']], 'Parçalamak miktarı değiştirir; aynı koşullarda maddenin cinsini değiştirmez.'),
    B('Yüzeydeki davranış tanecik çekiminden doğar',`Bir sıvının damla oluşturması, yüzeye yayılması ve ince boruda yükselmesi tanecikler arası etkileşimlerle ilişkilidir. Aynı maddenin tanecikleri arasındaki çekim kohezyon, farklı maddeler arasındaki çekim adezyondur. Sıvının boru yüzeyiyle etkileşimi uygun olduğunda kılcallıkla yükselme görülebilir; her sıvı her boruda yükselmez. Yüzey gerilimi de sıvı yüzeyinin alanını küçültmeye eğilimli davranışını açıklar. Bu kavramları yalnız damlanın şekline bakarak aynı şey sayma. Sıvının cinsi, yüzeyin yapısı ve sıcaklık değiştiğinde gözlenen davranışın değişebilmesi bu ayrımın sonucudur.`, 'cause', [['Kohezyon','Aynı tür taneciklerin çekimi'],['Adezyon','Farklı maddeler arasındaki çekim'],['Yüzey gerilimi','Yüzeyin alanını küçültme eğilimi'],['Kılcallık','İnce aralıkta yükselme veya alçalma']], 'Makroskobik gözlem, tanecik etkileşimlerinin birlikte etkisini yansıtır.'));

  R('fiz-tyt-03','Isı enerji aktarımıdır; sıcaklık bir cismin durumunu tanımlar. İkisini aynı nicelik gibi kullanma.',
    B('Isı aktarımı sıcaklığı nasıl değiştirir?',`Sıcaklıkları farklı iki cisim temas ettiğinde enerji kendiliğinden sıcaktan soğuğa aktarılır. Bu aktarımı ısı diye adlandırırız; cismin içinde depolanan ısıdan değil iç enerjiden söz ederiz. Hâl değişimi yoksa alınan enerji Q = m·c·ΔT bağıntısıyla ilişkilidir. Aynı enerji, kütlesi veya öz ısısı daha büyük örnekte daha küçük sıcaklık artışı oluşturur. Isıl dengeye gelindiğinde sıcaklıklar eşitlenir; kütlelerin veya iç enerjilerin eşit olması gerekmez. Metalin tahtadan soğuk hissedilmesi de sıcaklıklarından önce ısı iletim hızlarıyla ilgili olabilir.`, 'process', [['Sıcaklık farkı','Aktarımın yönünü belirler'],['Isı','Aktarılan enerji'],['Kütle ve öz ısı','Sıcaklık değişiminin büyüklüğü'],['Isıl denge','Net aktarımın durması']], 'Aynı sıcaklık, aynı iç enerji demek değildir.'),
    B('Isıtma grafiğinde yatay çizgi ne anlatır?',`Saf bir madde sabit basınçta erirken aldığı enerji, tanecikler arasındaki düzenin değişmesine harcanabilir; sıcaklık sabit kalır. Bu yüzden ısıtma grafiğindeki yatay bölüm enerji alınmadığını göstermez. Hâl değişimi tamamlandığında verilen enerji yeniden sıcaklığı artırabilir. Enerji iletiminde iletim komşu taneciklerin etkileşimiyle, konveksiyon akışkanın hareketiyle, ışınım elektromanyetik dalgalarla gerçekleşir. Işınım boşlukta da gerçekleşebildiğinden Güneş enerjisi Dünya’ya ulaşabilir. Grafiği yorumlarken maddenin saf olup olmadığını, basıncı ve yatay eksenin zaman mı aktarılan enerji mi olduğunu kontrol et.`, 'process', [['Isınma','Sıcaklığın artması'],['Hâl değişimi','Enerji alırken sıcaklığın sabit kalabilmesi'],['Yeni hâl','Isınmanın sürmesi'],['Aktarım yolları','İletim, konveksiyon ve ışınım']], 'Yatay sıcaklık çizgisi, enerji alışverişinin durduğunun kanıtı değildir.'));

  R('fiz-tyt-04','Hareket grafiğinin eğimi ve alanı farklı fiziksel bilgileri taşır.',
    B('Grafikte eğim ile alanı ayır',`Konum-zaman grafiğinin eğimi hızı verir; yatay olması cismin konumunun değişmediğini gösterir. Hız-zaman grafiğinin eğimi ise ivmedir. Bu grafikte zaman ekseniyle eğri arasında kalan işaretli alan yer değiştirmeyi verir; eksenin altındaki bölge negatif katkı yapar. Toplam alınan yol için bu alanların büyüklükleri toplanır. Böylece eşit pozitif ve negatif alanlar yer değiştirmeyi sıfırlayabilir, fakat yolu sıfırlamaz. Grafiğin yukarıda veya aşağıda bulunmasıyla eğiminin pozitif veya negatif olmasını birbirine karıştırma; bunlar farklı değişkenleri anlatır.`, 'compare', [['Konum–zaman eğimi','Hız'],['Hız–zaman eğimi','İvme'],['İşaretli alan','Yer değiştirme'],['Alan büyüklükleri toplamı','Alınan yol']], 'Önce eksenleri adlandır; aynı şekil farklı grafikte farklı anlam taşır.'),
    B('Net kuvvet hareketi değil hızı değiştirir',`Sabit kütleli bir cisimde net kuvvet, kütle ile ivmenin çarpımına eşittir. Net kuvvet sıfırsa ivme yoktur; cisim durabilir veya sabit hızla doğrusal hareket edebilir. Bu nedenle hareket eden her cisme ileri yönde net kuvvet gerektiği düşüncesi yanlıştır. Hız ve ivme aynı yöndeyse sürat artar, zıt yöndeyse azalır. Etki-tepki kuvvetleri ise farklı cisimlere uygulandığı için tek cismin kuvvet bilançosunda birbirini götürmez. Önce incelenen cismi seçmek, kuvvetleri doğru toplamanın temel adımıdır.`, 'process', [['Cisim seçimi','Hangi kuvvetler bu cisme etki ediyor?'],['Bileşke','Vektörel net kuvvet'],['İvme','Hız vektörünün değişimi'],['Sürat yorumu','Hız ile ivmenin yön ilişkisi']], 'Net kuvvetin yokluğu hareketin yokluğu anlamına gelmez.'));

  R('fiz-tyt-05','İş, kuvvetin yer değiştirme üzerinden enerji aktarmasını; güç bu aktarımın hızını anlatır.',
    B('Hangi kuvvet ne kadar iş yapar?',`Sabit kuvvetin yaptığı iş, yer değiştirme doğrultusundaki bileşeniyle uzaklığın çarpımıdır. Kuvvet yer değiştirmeye dikse o kuvvetin işi sıfırdır. Yatay taşınan çantaya yer çekiminin yaptığı işin sıfır olması bu yüzden mümkündür; insanın hiç enerji harcamadığını göstermez. Kuvvet hareketi destekliyorsa pozitif, ters yönde etkiliyorsa negatif iş yapabilir. Cisme etki eden kuvvetlerin net işi kinetik enerjideki değişime eşittir. Aynı kütlede sürati iki katına çıkarmak kinetik enerjiyi dört katına çıkarır; hızla enerji doğrusal değişmez.`, 'process', [['Kuvvet bileşeni','Yer değiştirmeye paralel bölüm'],['İşaret','Destekleyen veya karşı koyan etki'],['Net iş','Bütün kuvvetlerin toplam işi'],['Kinetik enerji','Hızın karesiyle ilişki']], 'Tek kuvvetin işi ile bütün kuvvetlerin net işi farklı olabilir.'),
    B('Mekanik enerji azalınca toplam enerji ne olur?',`Yüksekteki cismin yer çekimi potansiyel enerjisi, düşerken kinetik enerjiye dönüşebilir. Yalnız korunumlu kuvvetlerin iş yaptığı ideal düzende toplam mekanik enerji sabittir. Sürtünmeyle yavaşlayan cisimde mekanik enerji azalırken cisim ve çevrenin iç enerjisi artabilir; toplam enerji yok olmaz. Güç, işin yapılma veya enerjinin aktarılma hızıdır. Aynı yükü aynı yüksekliğe daha kısa sürede çıkaran düzenek daha büyük ortalama güç kullanır. Verim ise yararlı çıktının girdiye oranıyla ilgilidir; büyük güç her durumda büyük verim demek değildir.`, 'compare', [['Potansiyel','Konuma bağlı enerji'],['Kinetik','Harekete bağlı enerji'],['İç enerji','Sürtünmeyle artabilen bölüm'],['Güç ve verim','Aktarım hızı ile yararlı pay']], 'Enerji dönüşümünü, aktarım hızını ve yararlı oranı ayrı değerlendir.'));

  R('fiz-tyt-06','Sıvıdaki noktasal basınç ile cismin tamamına uygulanan kaldırma kuvveti farklı sonuçları açıklar.',
    B('Derinlik basıncı neden artırır?',`Durgun sıvıda daha derindeki noktanın üzerinde daha yüksek sıvı sütunu bulunur. Sıvının oluşturduğu basınç P = ρ·g·h bağıntısıyla derinliğe, özkütleye ve yer çekimi ivmesine bağlıdır. Su için g on kabul edildiğinde iki metre derinlikte sıvı basıncı yirmi kilopascaldır. Açık kaptaki toplam basınca atmosferin etkisi de eklenir. Kap genişliği bu noktadaki basıncı değiştirmez; ancak basınç kuvveti yüzey alanına da bağlıdır. Aynı basıncın farklı büyüklükte yüzeylere uygulanması aynı toplam kuvveti vermek zorunda değildir.`, 'cause', [['Derinlik','Üstteki sıvı sütunu'],['Özkütle','Aynı hacimdeki sıvı ağırlığı'],['Basınç','Birim alana etki'],['Basınç kuvveti','Basınç ile yüzey alanının etkisi']], 'Basınç pascal, kuvvet newton ile ölçülür; birbirlerinin yerine kullanılamaz.'),
    B('Yüzme koşulunda batan hacim değişir',`Bir cismin alt ve üst yüzeylerine etkiyen sıvı basınçları farklı olduğundan net bir kaldırma etkisi doğar. Kaldırma kuvveti, yer değiştirilen sıvının ağırlığına eşittir; sıvının özkütlesi ve cismin sıvı içindeki hacmi önemlidir. Başka düşey kuvvet yokken dengede yüzen cisimde bu kuvvet ağırlığa eşittir. Aynı cisim daha yoğun sıvıya konulduğunda daha az hacmi batarak aynı ağırlığı dengeleyebilir. Bu yüzden yoğun sıvıdaki yüzen cisme mutlaka daha büyük kaldırma kuvveti etkir demek yanlıştır; denge koşulunu önce kontrol et.`, 'process', [['Basınç farkı','Alt ve üst yüzey etkileri'],['Yer değiştiren sıvı','Batan hacim'],['Kaldırma kuvveti','Bu sıvının ağırlığı'],['Yüzme dengesi','Kaldırma kuvveti = ağırlık']], 'Daha yoğun sıvıda batan hacim azalabilir; dengedeki kuvvet aynı kalabilir.'));

  R('fiz-tyt-07','Elektriklenmeyi yük korunumu, yük aktarımı ve yeniden dağılım olarak üç adımda incele.',
    B('Yük türü ile elektron hareketi',`Sıradan katılarda elektriklenme çoğunlukla elektronların aktarılmasıyla gerçekleşir; protonlar çekirdek içinde bağlı kalır. Elektron kaybeden cisim pozitif, elektron alan cisim negatif yüklenebilir. Bu süreçte iki cisim ve çevre birlikte düşünüldüğünde toplam yük korunur. Sürtünme yeni yük yaratmaz, uygun maddeler arasında aktarımı kolaylaştırır. Dokunmada yük paylaşımı cismin geometrisine ve başlangıç durumuna bağlıdır; her zaman eşit miktar paylaşılacağını varsayma. Aynı işaretli yüklerin itmesi ve zıt işaretli yüklerin çekmesi, yük türlerini karşılaştırırken kullanılan temel davranıştır.`, 'process', [['Elektron aktarımı','Cisimler arasında yük hareketi'],['Elektron kaybı','Pozitif yüklenme'],['Elektron kazanımı','Negatif yüklenme'],['Korunum','Toplam yükün değişmemesi']], 'Elektriklenme, sıradan koşullarda atom çekirdeklerinin yer değiştirmesi değildir.'),
    B('Nötr cisim neden çekilebilir?',`Yüklü bir çubuk nötr iletkene yaklaştırıldığında serbest elektronların dağılımı değişebilir. Yakın tarafta zıt, uzak tarafta aynı işaretli yük yoğunlaşması oluşabilir; bütün cismin net yükü yine sıfır kalır. Bu nedenle çekim gözlemek, iki cismin kesinlikle zıt yüklü olduğunu kanıtlamaz. Etkiyle yük ayrışması ile topraklama kullanılarak net yük kazandırılması farklı işlemlerdir. Elektrik alanın yönü pozitif deneme yüküne etki eden kuvvetle tanımlanır; negatif yükün gördüğü kuvvet ters yöndedir. Önce net yükü, sonra yüklerin konumunu ayrı ayrı incele.`, 'compare', [['Nötr başlangıç','Toplam pozitif ve negatif yük eşit'],['Yaklaşan çubuk','Alanla yeniden dağılım'],['Ayrışmış durum','Net yük değişmeden kutuplanma'],['Kuvvet','Yakın ve uzak etkilerin bileşkesi']], 'Net yükün sıfır olması, her noktada yük etkisinin sıfır olması değildir.'));

  R('fiz-tyt-08','Bağlantı noktaları seri ve paraleli belirler; çizimin görünüşü tek başına yeterli değildir.',
    B('Gerilim, akım ve direnç nasıl bağlanır?',`Akım, bir kesitten birim zamanda geçen yük miktarıdır. Gerilim birim yük başına enerji farkını, direnç ise akıma karşı devre elemanının davranışını anlatır. Sıcaklığı sabit ohmik dirençte I = V/R geçerlidir. Altı voltluk ideal kaynağa üç ohm bağlanırsa akım iki amperdir. Direnç altı ohma çıkarıldığında aynı gerilimde akım bir ampere iner. Pilin sabit gerilim sağlaması sabit akım sağladığı anlamına gelmez; akımı bağlı devrenin eşdeğer direnci belirler. Gerçek kaynaklarda iç direnç de sonucu etkileyebilir.`, 'cause', [['Gerilim','Birim yüke sağlanan enerji'],['Direnç','Akımı sınırlayan etki'],['Akım','V/R ile belirlenen değer'],['İdeal varsayım','Sabit gerilim ve sabit direnç']], 'Bir değişkenin etkisini incelemek için diğerinin sabit tutulduğunu kontrol et.'),
    B('Aynı lambayı seri ve paralelde düşün',`Seri bağlı dirençlerde tek yol bulunduğundan akım aynıdır; kaynak gerilimi elemanlar arasında paylaşılır. Paralel kollarda ise uçlar aynı iki düğüme bağlı olduğundan gerilim aynıdır, toplam akım kollara ayrılır. İdeal pile yeni paralel lamba eklemek eski lambanın gerilimini değiştirmez; direnci sabitse gücü de aynı kalır. Fakat pilin toplam akımı artar. Parlaklığı karşılaştırırken P = V·I veya eşdeğer bağıntıları kullanmak gerekir. Yalnız akıma bakarak farklı dirençli iki lambanın her durumda aynı parlaklıkta olduğunu söyleyemezsin.`, 'compare', [['Seri','Aynı akım, paylaşılan gerilim'],['Paralel','Aynı gerilim, ayrılan akım'],['Toplam direnç','Bağlantıyla değişir'],['Lamba gücü','V·I ile değerlendirilir']], 'Eski kolun akımıyla kaynağın toplam akımı aynı kavram değildir.'));

  R('fiz-tyt-09','Manyetik alanı kutuplarla ve akımla oluşturulan ortak bir etki olarak düşün.',
    B('Kutuplar ve alan çizgileri',`Çubuk mıknatısın kuzey ve güney kutupları birlikte bulunur. Aynı kutuplar iter, zıt kutuplar çeker; mıknatısı ikiye bölmek tek kutbu ayırmaz, her parçada yeniden iki kutuplu yapı oluşur. Manyetik alan çizgileri mıknatıs dışında kuzeyden güneye yönelen bir modeldir. Çizgilerin daha sık gösterilmesi alanın daha güçlü olduğu bölgeyi temsil eder; çizgiler gerçek maddesel ipler değildir. Pusula iğnesi de bulunduğu yerdeki bileşke alana yönelir. Yakındaki bir mıknatısın pusulayı saptırması, yerel alanın Dünya alanıyla birleşmesinden kaynaklanır.`, 'process', [['Mıknatıs','Birlikte bulunan iki kutup'],['Alan modeli','Yön ve göreli şiddet'],['Pusula','Yerel bileşke alana yönelme'],['Bölme','Yeni iki kutuplu parçalar']], 'Çizim alanın dağılışını temsil eder; çizginin kendisi fiziksel bir cisim değildir.'),
    B('Elektrik akımı manyetik etki oluşturur',`Akım taşıyan tel çevresinde manyetik alan oluşur. Telin etrafındaki alanın yönü akım yönüne bağlıdır; akım ters çevrilince alan yönü de ters döner. Yalnız yönün değişmesi, alan büyüklüğünün mutlaka arttığı anlamına gelmez. Akım şiddeti, tele uzaklık ve düzenek geometrisi büyüklüğü etkiler. Tel bobin hâline getirildiğinde farklı sarımların etkileri uygun biçimde birleşir; çekirdek kullanımı elektromıknatısı güçlendirebilir. Böylece manyetik etki akımla kontrol edilebilir. Deneyde akım artırılırken diğer koşulların aynı tutulması, değişimin nedenini doğru belirlemek için önemlidir.`, 'cause', [['Akım taşıyan tel','Çevrede manyetik alan'],['Akım yönü','Alan yönünün değişmesi'],['Akım ve uzaklık','Alan büyüklüğünün etkilenmesi'],['Bobin ve çekirdek','Kontrol edilebilir elektromıknatıs']], 'Yön ve büyüklük iki ayrı bilgidir; ikisini tek değişken sanma.'));

  R('fiz-tyt-10','Dalga kavramlarını öğrenip aynı değişim mantığını ışığın ortam ve mercek davranışına uygula.',
    B('Kaynak frekansı ve ortam hızı',`Dalga, enerji aktarırken ortam taneciklerinin bütünüyle dalgayla birlikte ilerlemesini gerektirmez. Bir ipteki tanecik yerinde titreşirken şekil ip boyunca yayılabilir. Frekans kaynağın saniyedeki titreşim sayısı, dalga boyu ardışık eş fazlı noktalar arasındaki uzaklıktır. v = f·λ bağıntısı bu üçünü bağlar. Kaynak değişmeden başka ortama geçildiğinde frekans aynı kalırken hız ve dalga boyu değişebilir. Ses mekanik dalga olduğundan boşlukta yayılmaz; ışık ise elektromanyetik dalga olarak boşlukta yayılabilir. Genlik ile frekansı da ayır: daha büyük titreşim her zaman daha sık titreşim değildir.`, 'compare', [['Kaynak','Frekansı belirler'],['Ortam','Yayılma hızını etkiler'],['Dalga boyu','Hız/frekans ilişkisi'],['Genlik','Titreşimin büyüklüğü']], 'Bir dalga görüntüsü, taneciğin uzayda izlediği yolun resmi değildir.'),
    B('Işınları normale ve odağa göre oku',`Yansımada gelme ve yansıma açıları yüzeye değil normale göre ölçülür. Kırılmada daha büyük indisli ortama eğik giren ışık yavaşlar ve normale yaklaşır; frekansı değişmez. Havada ince kenarlı mercek asal eksene paralel ışınları odakta toplar. Gerçek cisim odak dışındaysa karşı tarafta ters ve gerçek görüntü, odak içindeyse aynı tarafta düz ve sanal görüntü oluşabilir. Sanal görüntüde kesişenler ışınların geri uzantılarıdır, gerçek ışık yolları değildir. Dolayısıyla merceğin her durumda büyüttüğünü söyleyemezsin; sonuç cismin odağa göre yerine bağlıdır.`, 'process', [['Normal','Açıların ölçüldüğü doğrultu'],['Ortam geçişi','Hız ve yön değişimi'],['Odak dışı cisim','Ters, gerçek görüntü'],['Odak içi cisim','Düz, sanal görüntü']], 'Görüntünün gerçekliği, ışınların mı geri uzantıların mı kesiştiğine bağlıdır.'));

  R('fiz-ayt-01','Vektörler hareketi doğru referansta tanımlar; denge hem öteleme hem dönme açısından incelenir.',
    B('Vektör bileşenleri ve bağıl hareket',`Kuvvetleri toplarken yalnız büyüklüklerini toplamak yeterli değildir; seçilen eksenlerdeki bileşenlerin yön ve işaretleri gerekir. İki araç aynı yönde yirmi ve on beş metre bölü saniyeyle gidiyorsa hızlı aracın diğerine göre hızı beş metre bölü saniyedir. Bağıl hızda gözlenenin hızından gözlemcinin hızı vektörel çıkarılır. Ardından net kuvvetle ivme ilişkisi kurulur: sabit kütlede Fnet = m·a. Normal kuvvetin her zaman ağırlığa eşit olduğunu ezberleme; eğim, başka kuvvetler ve sistemin ivmesi bu eşitliği değiştirebilir.`, 'process', [['Referans seçimi','Hızların aynı sistemde yazılması'],['Vektörel işlem','Bileşen ve işaretler'],['Net kuvvet','Bütün dış etkilerin bileşkesi'],['İvme','Kütle merkezinin hız değişimi']], 'Önce referansı ve cismi seç; sonra denklemi kur.'),
    B('Tork neden ikinci bir koşul gerektirir?',`Tork, kuvvetin seçilen noktaya göre döndürme etkisidir. Büyüklüğü kuvvetle, etki çizgisinin dönme noktasına dik uzaklığına bağlıdır. Eşit ve zıt iki kuvvet farklı doğrular boyunca uygulanırsa toplam kuvvet sıfır, toplam tork sıfırdan farklı olabilir; cisim ötelenmeden dönmeye başlayabilir. Bu nedenle durağan bir cismin statik dengesi için hem net kuvvet hem net tork sıfır olmalıdır. Uzaklığı cismin toplam boyu sanma; önemli olan kuvvetin etki çizgisine dik moment koludur. Dönme noktası seçimi hesabı kolaylaştırabilir, fiziksel sonucu değiştirmez.`, 'compare', [['Öteleme bilançosu','Net kuvvet'],['Dönme bilançosu','Net tork'],['Moment kolu','Etki çizgisine dik uzaklık'],['Statik denge','İki toplam da sıfır']], 'Kuvvetlerin dengesi, torkların dengesini kendiliğinden garanti etmez.'));

  R('fiz-ayt-02','Aynı kuvveti konuma göre ve zamana göre izlemek farklı değişimleri açıklar.',
    B('İş ve itmenin grafik anlamı',`Kuvvet-konum grafiğinde işaretli alan işi, kuvvet-zaman grafiğinde işaretli alan itmeyi verir. Net iş kinetik enerji değişimine, net itme momentum değişimine eşittir. Bu iki eşitlik aynı görünse de farklı büyüklükleri bağlar. Momentum kütle ile hızın vektörel çarpımıdır; kinetik enerji ise hızın karesine bağlı skaler büyüklüktür. Aynı momentum değişimini daha uzun sürede sağlamak ortalama kuvveti azaltabilir; hava yastığı örneği bu mantıkla anlaşılır. Grafiği okumadan önce yatay eksenin konum mu zaman mı olduğunu kesinleştir.`, 'compare', [['F–x alanı','İş ve kinetik enerji değişimi'],['F–t alanı','İtme ve momentum değişimi'],['Momentum','Yön taşıyan büyüklük'],['Kinetik enerji','Hızın karesine bağlı skaler']], 'Benzer grafik şekli, eksen değişince farklı fiziksel anlam kazanır.'),
    B('Çarpışmada korunumu sistem belirler',`İki cismi birlikte sistem seçtiğinde birbirlerine uyguladıkları kuvvetler iç kuvvettir. Net dış itme ihmal edilebiliyorsa sistemin toplam momentumu çarpışma boyunca korunur. Tek cismin momentumu ise değişebilir. Esnek çarpışmada toplam kinetik enerji de korunur; yapışmalı çarpışmada bir bölümü şekil değiştirme, ısınma veya ses gibi biçimlere dönüşebilir. Toplam enerjinin korunmasıyla kinetik enerjinin korunmasını birbirinin yerine kullanma. Önce sistem sınırını ve dış etkileri belirlemek, hangi korunum denklemini yazabileceğini gösterir; çarpışma sözcüğü tek başına bütün büyüklüklerin korunduğu anlamına gelmez.`, 'process', [['Sistem seçimi','İki cismi birlikte inceleme'],['Dış itme','Korunum koşulunun kontrolü'],['Momentum','Koşul sağlanırsa toplam sabit'],['Enerji türü','Esnek ve yapışmalı ayrımı']], 'Korunum, adı ezberlenen değil koşulu sınanan bir ilkedir.'));

  R('fiz-ayt-03','İki boyutlu harekette hızın yönü değişebilir; süratin sabitliği ivmenin yokluğu değildir.',
    B('Atışta yatay ve düşey hareketi ayır',`Hava direnci yokken, yer yüzeyine yakın atışta yatay doğrultuda net kuvvet bulunmaz; yatay hız sabit kalır. Düşey doğrultuda ise yer çekimi ivmesi aşağı yönlüdür. İki bileşen aynı zaman boyunca gerçekleşir. Bu nedenle aynı yükseklikten yatay atılan ve serbest bırakılan iki cismin yere ulaşma süreleri eşit olabilir. Eğik atışın tepesinde düşey hız sıfırlanır, fakat yatay hız sürer ve ivme aşağı yönlü kalır. Tepe noktasını bütün hareketin durduğu ya da kuvvetin yok olduğu an olarak yorumlama.`, 'compare', [['Yatay bileşen','Sabit hız'],['Düşey bileşen','Aşağı yönlü ivme'],['Ortak zaman','İki bileşenin eş zamanlı gelişmesi'],['Tepe noktası','Yalnız düşey hız sıfır']], 'Bileşenlerden birinin sıfır olması bütün vektörün sıfır olması değildir.'),
    B('Çembersel harekette yön değişimini izle',`Düzgün çembersel harekette sürat sabittir; fakat teğetsel hızın yönü sürekli değişir. Bu değişim merkeze doğru ivme gerektirir ve büyüklüğü v²/r ile belirlenir. Merkezcil kuvvet ayrı bir kuvvet türü değildir; ip gerilmesi, sürtünme veya çekim gibi gerçek kuvvetlerin merkez yönündeki bileşkesidir. Aynı yarıçapta sürati iki katına çıkarmak gereken merkezcil kuvveti dört katına çıkarır. Dönmede kütlenin eksene dağılımı da eylemsizlik momentini etkiler. Net dış tork sıfırken açısal momentumun korunması, bu dağılım değiştiğinde açısal hızın değişebilmesini açıklar.`, 'cause', [['Teğetsel hız','Anlık hareket yönü'],['Merkezcil ivme','Hız yönünün değişimi'],['Gerçek kuvvetler','Merkez yönündeki bileşke'],['Dağılım ve tork','Dönme hareketinin koşulları']], 'Dışarıya doğru yeni bir kuvvet eklemek yerine gerçek kuvvetleri merkeze göre çözümle.'));

  R('fiz-ayt-04','Basit harmonik harekette konum, hız ve ivmenin en büyük olduğu yerler farklıdır.',
    B('Geri çağırıcı kuvvet ve enerji dönüşümü',`İdeal yatay yay düzeneğinde cisim denge konumundan uzaklaştırıldığında yay onu dengeye doğru çeker. Kuvvetin büyüklüğü uzanımla orantılı, yönü uzanıma terstir. Uç noktada hız sıfırdır; buna karşılık kuvvet ve ivme büyüklükleri en büyüktür. Dengeye yaklaşırken yay potansiyel enerjisi kinetik enerjiye dönüşür. Denge noktasında uzanım ve ivme sıfır, sürat en büyüktür. Cisim durmadığı için karşı tarafa geçer; kuvvet artık onu geri yönlendirir. Uçta duraklamayı enerjinin yok olmasıyla karıştırma; enerji o anda farklı biçimdedir.`, 'cycle', [['Sağ uç','Hız sıfır, kuvvet sola'],['Denge geçişi','Sürat en büyük, ivme sıfır'],['Sol uç','Hız sıfır, kuvvet sağa'],['Dönüş','Enerjinin yeniden yer değiştirmesi']], 'Bir noktada hızın sıfır olması ivmenin de sıfır olduğunu göstermez.'),
    B('Periyot sorusunda modelin koşulunu seç',`Yay sarkacında kütlenin büyümesi periyodu artırır; daha sert yay, yani daha büyük yay sabiti periyodu azaltır. İdeal modelde genlik değişimi periyodu değiştirmez, fakat toplam enerjiyi değiştirir. Basit sarkaçta küçük açı yaklaşımı kullanıldığında periyot uzunluğa ve yer çekimi ivmesine bağlıdır; sarkaç kütlesine bağlı değildir. Uzun ip daha uzun periyot verir. Genliği çok büyütüp küçük açı koşulunu bozarsan aynı bağıntıyı sınırsız kullanamazsın. Önce yay mı basit sarkaç mı olduğunu, sonra hangi ideal varsayımların verildiğini belirle.`, 'compare', [['Yay sarkacı','Kütle ve yay sabiti'],['Basit sarkaç','Uzunluk ve yer çekimi'],['Genlik','Enerjiyi etkileyen büyüklük'],['Model sınırı','Küçük açı ve sürtünmesizlik']], 'Periyot bağıntısı, kullanılan düzeneğin ve yaklaşımın sınırları içinde geçerlidir.'));

  R('fiz-ayt-05','Çekim, uydu hareketi ve Kepler yasaları aynı merkezî etkileşimin farklı görünümleridir.',
    B('Yükseklik yerine merkeze uzaklık',`Kütle çekim kuvveti iki kütlenin çarpımıyla doğru, aralarındaki uzaklığın karesiyle ters orantılıdır. Küresel cisimler için bu uzaklık merkezler arasında ölçülür; Dünya yüzeyinden yükseklikle aynı değildir. Merkeze uzaklık iki katına çıkarsa aynı kütleler arasındaki kuvvet dörtte birine iner. Yüzeyden uzaklaştıkça çekim azalır, ama hemen sıfırlanmaz. Çembersel yörüngedeki uyduyu merkeze yönelten kuvvet de çekimdir. Uydu yatay hareketiyle birlikte sürekli düşerken gezegenin yüzeyine çarpmadan çevresinde dolanabilir; çekimden kurtulduğu için yörüngede kalmaz.`, 'process', [['Merkezler arası uzaklık','Çekim bağıntısındaki r'],['Ters kare','Uzaklık büyüdükçe kuvvet azalır'],['Merkezcil etki','Yörüngeyi sağlayan çekim'],['Sürekli düşüş','Uydu hareketinin mekanizması']], 'Uzayda bulunmak, yer çekiminin bulunmadığı anlamına gelmez.'),
    B('Dolanım süresi ve ağırlıksızlık',`Aynı gezegenin çevresindeki daha geniş çembersel yörüngede uydu daha yavaş hareket eder ve bir turu daha uzun sürede tamamlar. Kepler’in dönem yasasında sürenin karesi, büyük yarı eksenin küpüyle orantılıdır. Eliptik yörüngede eşit zamanlarda eşit alanlar taranması, uydu merkezî cisme yaklaşırken hızlanmasını açıklar. Uydu içindeki astronot da araçla birlikte serbest düşüştedir; destek kuvvetinin yokluğu ağırlıksızlık hissi oluşturabilir. Bu durum çekim kuvvetinin sıfır olduğunu göstermez. Yörüngeyi, hızı ve hissedilen ağırlığı aynı büyüklük olarak düşünmemek gerekir.`, 'compare', [['Yakın yörünge','Daha yüksek çembersel hız'],['Uzak yörünge','Daha uzun dolanım süresi'],['Elips','Eşit zamanda eşit alan'],['Ağırlıksızlık','Destek kuvveti olmadan serbest düşüş']], 'Çekim kuvveti ile tartının göstereceği destek kuvveti aynı şey değildir.'));

  R('fiz-ayt-06','Elektrik alan kuvveti yönlendirir; potansiyel enerji hesabında skaler bir başlangıç sağlar.',
    B('Alanı ve potansiyeli farklı topla',`Elektrik alan, pozitif birim deneme yüküne düşen kuvvet olarak tanımlanır ve vektöreldir. Pozitif kaynaktan dışarı, negatif kaynağa doğru yönelir. Elektriksel potansiyel ise birim yük başına potansiyel enerjidir ve skalerdir; seçilen sıfır düzeyine göre işaret alır. İki eşit pozitif yükün orta noktasında alanlar zıt yönlü olduğundan birbirini götürür. Sonsuzda sıfır seçilen potansiyeller ise pozitif olarak toplanır. Dolayısıyla alanın sıfır olması potansiyelin de sıfır olmasını gerektirmez; vektörel ve cebirsel toplamın farkı burada doğrudan görünür.`, 'compare', [['Elektrik alan','Yönlü kuvvet/yük bilgisi'],['Potansiyel','Skaler enerji/yük bilgisi'],['Orta nokta alanı','Eşit ve zıt katkılar'],['Orta nokta potansiyeli','Aynı işaretli katkıların toplamı']], 'Bir noktadaki alan ile potansiyel farklı soruların cevaplarıdır.'),
    B('Yükün işareti enerji yorumunu değiştirir',`Bir yükün potansiyel enerji değişimi ΔU = q·ΔV ile bulunur. Pozitif yük için potansiyel artışı enerji artışı demekken negatif yükte aynı değişim ters sonuç verebilir. Elektrik alan yönünde potansiyel azalır; fakat kuvvetin yönü için ayrıca yükün işaretini bilmek gerekir. Eş potansiyel iki nokta arasında yük taşındığında elektriksel iş sıfırdır. Elektrostatik alan eş potansiyel yüzeylere diktir. Bu nedenle alan çizgisi ile eş potansiyel çizgisini aynı eğri gibi kullanma; biri yönü, diğeri sabit enerji/yük düzeyini gösterir.`, 'process', [['Potansiyel farkı','Başlangıç ve bitiş değerleri'],['Yükün işareti','q çarpanının etkisi'],['Enerji değişimi','q·ΔV'],['Eş potansiyel','Elektriksel işin sıfır olduğu yer değiştirme']], 'Potansiyelin azaldığı yönde her yükün potansiyel enerjisi aynı biçimde değişmez.'));

  R('fiz-ayt-07','Elektrik ve manyetizmada değişeni bul: gerilim mi yük mü, alan mı akı mı?',
    B('Sığaçta sabit kalan ne?',`Paralel levhalı sığaçta karşıt yükler ayrılarak elektrik alanda enerji depolanır. Sığa C = Q/V oranıdır; ideal düzenekte levha alanı, levhalar arası uzaklık ve yalıtkan ortam tarafından belirlenir. İdeal pile bağlı tutulursa gerilim sabittir; sığa değişince yük değişebilir. Pil ayrılmış, sistem yalıtılmış ve kaçaksızsa yük sabit kalır; bu kez gerilim değişebilir. İki duruma aynı sabitliği uygulamak hataya yol açar. Levhaların arasını değiştirme veya yalıtkan ekleme sorusunda önce bağlantıyı, sonra değişen geometrik özelliği belirlemek gerekir.`, 'compare', [['Geometri ve ortam','Sığayı belirler'],['Pile bağlı','Gerilim sabit'],['Yalıtılmış ve ayrık','Yük sabit'],['Enerji','Alan düzeninin sonucu']], 'Sığayı değiştirmekle gerilimi değiştirmek aynı işlem değildir.'),
    B('Manyetik kuvvet ve indüksiyonun farkı',`Hareketli yüke etki eden manyetik kuvvet hıza diktir; tek başına sürati değiştirmeden hareket yönünü değiştirebilir. İndüksiyonda ise kapalı devreden geçen manyetik akının zamanla değişimi önemlidir. Akı alan büyüklüğüne, yüzey alanına ve yüzey normalinin yönüne bağlı olduğundan yalnız mıknatısı hareket ettirmekle değil yüzeyi döndürmekle de değişebilir. Lenz yasası oluşan manyetik etkinin değişime karşı yöneldiğini anlatır. Sabit alan içindeki duran halkanın akısı değişmiyorsa bu nedenle sürekli indüksiyon akımı oluşmaz; alanın varlığı tek başına yeterli değildir.`, 'cause', [['Hareketli yük','Hıza dik manyetik kuvvet'],['Manyetik akı','Alan, yüzey ve yönelim'],['Akı değişimi','İndüksiyon elektromotor kuvveti'],['Lenz','Değişime karşı tepki']], 'Akıya karşı olmakla akının değişimine karşı olmak farklıdır.'));

  R('fiz-ayt-08','Alternatif akımın anlık değerini, etkin değerini ve enerji aktarımını ayrı incele.',
    B('Etkin değer neden kullanılır?',`Alternatif akımın yönü ve büyüklüğü zamanla değişebilir; sinüzoidal örnekte bir periyot boyunca pozitif ve negatif değerler alır. Akımın işaret değiştirmesi dirençte oluşan ısının birbirini götürdüğü anlamına gelmez, çünkü ısı etkisi akımın karesiyle ilişkilidir. Etkin değer, aynı dirençte aynı ortalama ısı etkisini oluşturan doğru akım değerini anlatır. Bu yüzden anlık akımın bir anda sıfır olması ortalama gücün de sıfır olduğunu göstermez. Grafikte tepe değerini etkin değerle karıştırmamak, enerji ve güç sorularının doğru yorumlanmasını sağlar.`, 'compare', [['Anlık değer','Belirli andaki akım'],['Tepe değer','En büyük büyüklük'],['Etkin değer','Eşdeğer ısı etkisi'],['Ortalama güç','Periyot boyunca enerji aktarımı']], 'Yönün ters dönmesi, dirençteki ısınmanın tersine dönmesi değildir.'),
    B('Transformatör enerji üretmez',`Transformatörün bir bobinindeki alternatif akım değişken manyetik akı oluşturur; bu akı ikinci bobinde gerilim indükler. İdeal modelde gerilim oranı sarım sayıları oranına eşittir. Çıkış gerilimi beş katına yükseltilirse aynı güçte akım beşte birine iner. Yüksek gerilimle enerji iletiminde hat akımının azalması, dirençteki I²R kaybını küçültür. Kararlı doğru akım sürekli değişken akı oluşturmadığından ideal transformatörde sürekli gerilim dönüşümü sağlamaz. Gerçek düzeneklerde kayıplar bulunduğu için yüzde yüz verim varsayımı ancak ideal model için geçerlidir.`, 'process', [['Birinci bobin','Değişken akım'],['Ortak manyetik akı','Enerji aktarım bağlantısı'],['İkinci bobin','İndüklenen gerilim'],['Sarım oranı','Gerilim artarken akımın azalması']], 'İdeal güç korunur; gerilimi artırmak bedelsiz güç artışı değildir.'));

  R('fiz-ayt-09','Dalga desenini oluşturmak için katkıların fazını, yayılma koşullarını ve gözlemciyi birlikte düşün.',
    B('Girişim ve kırınımın mekanizması',`İki dalga aynı noktaya ulaştığında bileşke uzanım katkıların toplamıdır. Uygun fazdaki katkılar genliği büyütür; zıt fazdakiler azaltabilir veya söndürebilir. Bir noktadaki söndürme, enerjinin bütün uzayda yok olduğu anlamına gelmez; desen içinde farklı dağılım vardır. Kırınım ise dalganın açıklık veya engel çevresinde yayılmasıdır. Açıklık boyutu dalga boyuna yaklaştığında belirginleşir. Su dalgası düzeneğinde açıklığı daraltmakla kaynağın frekansını değiştirmek farklı işlemlerdir. Hangisinin değiştiğini bilmeden desendeki değişimin tek nedenini söylemek doğru olmaz; diğer koşullar sabit tutulmalıdır.`, 'compare', [['Yapıcı girişim','Katkıların güçlenmesi'],['Yıkıcı girişim','Katkıların azalması'],['Kırınım','Açıklık veya engel çevresinde yayılma'],['Ölçek ilişkisi','Açıklık ile dalga boyunun karşılaştırılması']], 'Girişim üst üste binmeyi, kırınım yayılma biçimini anlatır.'),
    B('Saçak aralığı ve gözlenen frekans',`Çift yarıkta küçük açı yaklaşımıyla saçak aralığı λ·L/d bağıntısına uyar. Dalga boyu veya ekran uzaklığı artarsa aralık büyür; yarıklar arası uzaklık artarsa küçülür. Tek yarıkta açıklığın daralması merkezi aydınlık bölgeyi genişletebilir. Doppler olayında ise kaynakla gözlemcinin göreli hareketi gözlenen frekansı değiştirir; kaynağın kendi titreşimi değişmek zorunda değildir. Ses kaynağı yaklaşırken daha yüksek frekans duyulabilir, fakat durgun ortamın ses yayılma hızı bu yüzden değişmez. Desen ve frekans sorularında kaynağı, ortamı ve gözlem koşulunu ayrı ayrı izle.`, 'cause', [['Dalga boyu ve ekran','Saçakları açan etkenler'],['Yarık uzaklığı','Saçakları sıklaştıran etken'],['Kırınım açıklığı','Merkezi bölgenin genişliği'],['Göreli hareket','Gözlenen frekans değişimi']], 'Kaynak frekansı, ortam hızı ve gözlenen frekans farklı bilgilerdir.'));

  R('fiz-ayt-10','Atom ölçeğinde enerji ve momentum alışverişini izlemek, klasik sezgilerin sınırını gösterir.',
    B('Atom düzeyleri ve tek fotonun enerjisi',`Bohr modelinde elektronun izinli enerji düzeyleri vardır. Düzeyler arasındaki geçişte yayılan veya soğurulan fotonun enerjisi düzey farkına eşittir; çizgi spektrumlarının mantığı buradan anlaşılır. Foton enerjisi frekansla doğru orantılıdır. Fotoelektrik olayda metalden elektron koparmak için bu enerjinin iş fonksiyonunu karşılaması gerekir; kalan bölüm elektronun kinetik enerjisine dönüşebilir. Aynı frekansta ışık şiddetini artırmak foton sayısını artırır, tek fotonun enerjisini değil. Bu yüzden eşik altındaki ışığı güçlendirmek ideal tek fotonlu modelde elektron koparmaya yetmez.`, 'process', [['Enerji düzeyi','İzinli atom durumları'],['Foton','Düzey farkı kadar enerji'],['Eşik enerji','Elektronu koparma koşulu'],['Kalan enerji','Elektronun kinetik enerjisi']], 'Şiddet ile frekansın aynı değişken olmadığını tek etkileşim üzerinden gör.'),
    B('Parçacık ve dalga özellikleri birlikte gereklidir',`Compton olayında foton elektronla etkileşerek enerji ve momentum aktarabilir; saçılan fotonun dalga boyu büyüyebilir. Bu olay ışığın parçacık yönünü, girişim ve kırınım ise dalga yönünü açıklamada önemlidir. de Broglie yaklaşımı madde parçacıkları için de dalga boyu tanımlar: λ = h/p. Momentum arttığında dalga boyu azalır. Buradan parçacığın yalnız klasik küçük bir bilye veya yalnız su dalgası gibi davranacağını çıkarma. Kullanılan model, yapılan deneyde ölçülen olayı açıklamak için seçilir; tek benzetme bütün özellikleri eksiksiz karşılamaz.`, 'compare', [['Compton','Fotonun enerji ve momentum aktarımı'],['Girişim','Işığın dalga özelliği'],['de Broglie','Momentumla ters orantılı dalga boyu'],['Model seçimi','Deneyin gösterdiği özellik']], 'Dalga ve parçacık anlatımları farklı deney sonuçlarını birlikte anlamaya yardım eder.'),
    B('Çekirdekteki değişim her ışımada aynı değildir',`Radyoaktif olay çekirdekte gerçekleşir; sıradan kimyasal bağ değişimiyle aynı şey değildir. Uyarılmış çekirdek gama fotonu yayarak daha düşük enerji durumuna geçebilir. Bu sırada proton ve nötron sayısı değişmediğinden atom numarası da değişmez. Alfa yayımında ise çekirdek iki proton ve iki nötron kaybeder; dolayısıyla aynı sonuç beklenmez. Işımanın adını gördüğünde yalnız enerji çıkışını değil, çekirdeğin bileşiminin değişip değişmediğini de kontrol et. Kimyasal bir tepkimeyle nükleer dönüşümü karıştırmak, elementin kimliğine ilişkin yorumda hata doğurur.`, 'compare', [['Gama yayımı','Çekirdek enerjisinin azalması'],['Sayıların korunması','Proton ve nötron sayısı aynı'],['Alfa yayımı','İki proton ve iki nötron kaybı'],['Element kimliği','Proton sayısına bağlı']], 'Enerji yayılması, atom numarasının her durumda değiştiği anlamına gelmez.'),
    B('Zaman ve uzunluk hangi gözlemciye göre?',`Özel görelilikte fizik yasaları eylemsiz referans sistemlerinde aynı biçimdedir ve boşluktaki ışık hızı bütün eylemsiz gözlemciler için aynıdır. Bu ilkeler, farklı hareket durumlarındaki gözlemcilerin zaman aralığı ve uzunluğu aynı ölçmek zorunda olmadığını gösterir. Hareketli saatin iki atımı arasındaki süre, saatin yanında duran gözlemcinin ölçtüğü öz zamandan daha uzun ölçülebilir. Uzunluk kısalması hareket doğrultusunda değerlendirilir; her yönde aynı oranda küçülme değildir. Günlük hızlarda etkiler çok küçük olduğundan fark edilmez. Hesapta hangi gözlemcinin hangi ölçümü yaptığını belirtmek temel koşuldur.`, 'compare', [['Işık hızı','Boşlukta eylemsiz gözlemciler için aynı'],['Öz zaman','Saatle birlikte duran gözlemci'],['Göreli süre','Başka sistemde daha uzun ölçülebilme'],['Uzunluk','Hareket doğrultusunda kısalma']], 'Ölçülen niceliği, ölçümü yapan referans sistemiyle birlikte tanımla.'));

  window.READING = { ...(window.READING || {}), ...reading };
})();
